bool BackRefMatchesNoCase(Isolate* isolate, int from, int current, int len,
                          base::Vector<const base::uc16> subject,
                          bool unicode) {
  DRPERF_BENCH_REGION("v8-regexp-001");
  Address offset_a =
      reinterpret_cast<Address>(const_cast<base::uc16*>(&subject.at(from)));
  Address offset_b =
      reinterpret_cast<Address>(const_cast<base::uc16*>(&subject.at(current)));
  size_t length = len * base::kUC16Size;

  bool result = unicode
                    ? RegExpMacroAssembler::CaseInsensitiveCompareUnicode(
                          offset_a, offset_b, length, isolate)
                    : RegExpMacroAssembler::CaseInsensitiveCompareNonUnicode(
                          offset_a, offset_b, length, isolate);
  return result == 1;
}

bool BackRefMatchesNoCase(Isolate* isolate, int from, int current, int len,
                          base::Vector<const uint8_t> subject, bool unicode) {
  DRPERF_BENCH_REGION("v8-regexp-002");
  // For Latin1 characters the unicode flag makes no difference.
  for (int i = 0; i < len; i++) {
    unsigned int old_char = subject[from++];
    unsigned int new_char = subject[current++];
    if (old_char == new_char) continue;
    // Convert both characters to lower case.
    old_char |= 0x20;
    new_char |= 0x20;
    if (old_char != new_char) return false;
    // Not letters in the ASCII range and Latin-1 range.
    if (!(old_char - 'a' <= 'z' - 'a') &&
        !(old_char - 224 <= 254 - 224 && old_char != 247)) {
      return false;
    }
  }
  return true;
}

IrregexpInterpreter::Result HandleInterrupts(
    Isolate* isolate, RegExp::CallOrigin call_origin,
    Tagged<TrustedByteArray>* code_array_out,
    Tagged<String>* subject_string_out, const uint8_t** code_base_out,
    base::Vector<const Char>* subject_string_vector_out,
    const uint8_t** pc_out) {
  DRPERF_BENCH_REGION("v8-regexp-003");
  DisallowGarbageCollection no_gc;

  StackLimitCheck check(isolate);
  bool js_has_overflowed = check.JsHasOverflowed();

  if (call_origin == RegExp::CallOrigin::kFromJs) {
    // Direct calls from JavaScript can be interrupted in two ways:
    // 1. A real stack overflow, in which case we let the caller throw the
    //    exception.
    // 2. The stack guard was used to interrupt execution for another purpose,
    //    forcing the call through the runtime system.
    if (js_has_overflowed) {
      return IrregexpInterpreter::EXCEPTION;
    } else if (check.InterruptRequested()) {
      return IrregexpInterpreter::RETRY;
    }
  } else {
    DCHECK(call_origin == RegExp::CallOrigin::kFromRuntime);
    // Prepare for possible GC.
    HandleScope handles(isolate);
    DirectHandle<TrustedByteArray> code_handle(*code_array_out, isolate);
    DirectHandle<String> subject_handle(*subject_string_out, isolate);

    if (js_has_overflowed) {
      return ThrowStackOverflow(isolate, call_origin);
    } else if (check.InterruptRequested()) {
      const bool was_one_byte =
          String::IsOneByteRepresentationUnderneath(*subject_string_out);
      Tagged<Object> result;
      {
        AllowGarbageCollection yes_gc;
        result = isolate->stack_guard()->HandleInterrupts();
      }
      if (IsExceptionHole(result)) {
        return IrregexpInterpreter::EXCEPTION;
      }

      // If we changed between a LATIN1 and a UC16 string, we need to
      // restart regexp matching with the appropriate template instantiation of
      // RawMatch.
      if (String::IsOneByteRepresentationUnderneath(*subject_handle) !=
          was_one_byte) {
        return IrregexpInterpreter::RETRY;
      }

      UpdateCodeAndSubjectReferences(
          isolate, code_handle, subject_handle, code_array_out, code_base_out,
          pc_out, subject_string_out, subject_string_vector_out);
    }
  }

  return IrregexpInterpreter::SUCCESS;
}

bool CheckSpecialClassRanges(uint32_t current_char,
                             StandardCharacterSet character_set) {
  DRPERF_BENCH_REGION("v8-regexp-004");
  constexpr bool is_one_byte = sizeof(Char) == 1;
  switch (character_set) {
    case StandardCharacterSet::kWhitespace:
      DCHECK(is_one_byte);
      if (current_char == ' ' || base::IsInRange(current_char, '\t', '\r') ||
          current_char == 0xA0) {
        return true;
      }
      return false;
    case StandardCharacterSet::kNotWhitespace:
      UNREACHABLE();
    case StandardCharacterSet::kWord: {
      if constexpr (!is_one_byte) {
        if (current_char > 'z') {
          return false;
        }
      }
      base::Vector<const uint8_t> word_character_map =
          RegExpMacroAssembler::word_character_map();
      DCHECK_EQ(0,
                word_character_map[0]);  // Character '\0' is not a word char.
      return word_character_map[current_char] != 0;
      return true;
    }
    case StandardCharacterSet::kNotWord: {
      if constexpr (!is_one_byte) {
        if (current_char > 'z') {
          return true;
        }
      }
      base::Vector<const uint8_t> word_character_map =
          RegExpMacroAssembler::word_character_map();
      DCHECK_EQ(0,
                word_character_map[0]);  // Character '\0' is not a word char.
      return word_character_map[current_char] == 0;
    }
    case StandardCharacterSet::kDigit:
      if (base::IsInRange(current_char, '0', '9')) {
        return true;
      }
      return false;
    case StandardCharacterSet::kNotDigit:
      if (base::IsInRange(current_char, '0', '9')) {
        return false;
      }
      return true;
    case StandardCharacterSet::kLineTerminator: {
      if (current_char == '\n' || current_char == '\r') {
        return true;
      }
      if constexpr (!is_one_byte) {
        if (current_char == 0x2028 || current_char == 0x2029) {
          return true;
        }
      }
      return false;
    }
    case StandardCharacterSet::kNotLineTerminator: {
      const bool is_one_byte_match =
          current_char != '\n' && current_char != '\r';
      if constexpr (is_one_byte) {
        if (is_one_byte_match) {
          return true;
        }
      } else {
        if (is_one_byte_match && current_char != 0x2028 &&
            current_char != 0x2029) {
          return true;
        }
      }
      return false;
    }
    case StandardCharacterSet::kEverything:
      return true;
  }
  UNREACHABLE();
}

IrregexpInterpreter::Result RawMatch(
    Isolate* isolate, Tagged<TrustedByteArray>* code_array,
    Tagged<String>* subject_string, base::Vector<const Char> subject,
    int* output_registers, int output_register_count, int total_register_count,
    int current, uint32_t current_char, RegExp::CallOrigin call_origin,
    const uint32_t backtrack_limit) {
  DRPERF_BENCH_REGION("v8-regexp-005");
  DisallowGarbageCollection no_gc;

#if V8_USE_COMPUTED_GOTO

  // Maximum number of bytecodes that will be used (next power of 2 of actually
  // defined bytecodes).
  // All slots between the last actually defined bytecode and maximum id will be
  // filled with kBreaks, indicating an invalid operation. This way using
  // kBytecodeMask guarantees no OOB access to the dispatch table.
  constexpr int kPaddedBytecodeCount =
      base::bits::RoundUpToPowerOfTwo32(Bytecodes::kCount);
  constexpr int kBytecodeMask = kPaddedBytecodeCount - 1;
  static_assert(std::numeric_limits<uint8_t>::max() >= kBytecodeMask);

  // We have to make sure that no OOB access to the dispatch table is possible
  // and all values are valid label addresses. Otherwise jumps to arbitrary
  // addresses could potentially happen. This is ensured as follows: Every index
  // to the dispatch table gets masked using kBytecodeMask in DECODE(). This way
  // we can only get values between 0 (only the least significant byte of an
  // integer is used) and kPaddedBytecodeCount - 1 (kBytecodeMask is defined to
  // be exactly this value). All entries from Bytecodes::kCount to
  // kRegExpPaddedBytecodeCount are automatically filled with kBreak (invalid
  // operation).

#define DECLARE_DISPATCH_TABLE_ENTRY(name, ...) &&BC_k##name,
  static const void* const unsafe_dispatch_table[Bytecodes::kCount] = {
      REGEXP_BYTECODE_LIST(DECLARE_DISPATCH_TABLE_ENTRY)};
#undef DECLARE_DISPATCH_TABLE_ENTRY
#undef BYTECODE_FILLER_ITERATOR

  static const void* const filler_entry = &&BC_kBreak;
  static const std::array<const void*, kPaddedBytecodeCount> dispatch_table =
      [=]() {
        std::array<const void*, kPaddedBytecodeCount> table;

        size_t i = 0;
        // Copy all valid Bytecodes to the dispatch table.
        for (; i < Bytecodes::kCount; ++i) {
          table[i] = unsafe_dispatch_table[i];
        }
        // Fill dispatch table from last defined bytecode up to the next power
        // of two with kBreak (invalid operation).
        for (; i < kPaddedBytecodeCount; ++i) {
          table[i] = filler_entry;
        }
        return table;
      }();

#endif  // V8_USE_COMPUTED_GOTO

  const uint8_t* pc = (*code_array)->begin();
  const uint8_t* code_base = pc;

  InterpreterRegisters registers(total_register_count, output_registers,
                                 output_register_count);
  BacktrackStack backtrack_stack;

  uint32_t backtrack_count = 0;

  while (true) {
    const uint8_t* next_pc = pc;
#if V8_USE_COMPUTED_GOTO
    const void* next_handler_addr;
    DECODE();
    DISPATCH();
#else
    switch (Bytecodes::FromPtr(pc)) {
#endif  // V8_USE_COMPUTED_GOTO
    BYTECODES_START()
    BYTECODE(Break) { UNREACHABLE(); }
    BYTECODE(PushCurrentPosition) {
      ADVANCE();
      if (!backtrack_stack.push(current)) {
        return MaybeThrowStackOverflow(isolate, call_origin);
      }
      DISPATCH();
    }
    BYTECODE(PushBacktrack, label) {
      ADVANCE();
      if (!backtrack_stack.push(label)) {
        return MaybeThrowStackOverflow(isolate, call_origin);
      }
      DISPATCH();
    }
    BYTECODE(PushRegister, register_index, stack_check) {
      ADVANCE();
      USE(stack_check);  // Unused in interpreter.
      if (!backtrack_stack.push(registers[register_index])) {
        return MaybeThrowStackOverflow(isolate, call_origin);
      }
      DISPATCH();
    }
    BYTECODE(SetRegister, register_index, value) {
      ADVANCE();
      registers[register_index] = value;
      DISPATCH();
    }
    BYTECODE(ClearRegisters, from_register, to_register) {
      ADVANCE();
      SBXCHECK_LE(from_register, to_register);
      for (uint16_t i = from_register; i <= to_register; ++i) {
        registers[i] = InterpreterRegisters::kNoMatchValue;
      }
      DISPATCH();
    }
    BYTECODE(AdvanceRegister, register_index, by) {
      ADVANCE();
      registers[register_index] += by;
      DISPATCH();
    }
    BYTECODE(WriteCurrentPositionToRegister, register_index, cp_offset) {
      ADVANCE();
      registers[register_index] = current + cp_offset;
      DISPATCH();
    }
    BYTECODE(ReadCurrentPositionFromRegister, register_index) {
      ADVANCE();
      SET_CURRENT_POSITION(registers[register_index]);
      DISPATCH();
    }
    BYTECODE(WriteStackPointerToRegister, register_index) {
      ADVANCE();
      registers[register_index] = backtrack_stack.sp();
      DISPATCH();
    }
    BYTECODE(ReadStackPointerFromRegister, register_index) {
      ADVANCE();
      backtrack_stack.set_sp(registers[register_index]);
      DISPATCH();
    }
    BYTECODE(PopCurrentPosition) {
      ADVANCE();
      SET_CURRENT_POSITION(backtrack_stack.pop());
      DISPATCH();
    }
    BYTECODE(Backtrack, return_code) {
      static_assert(JSRegExp::kNoBacktrackLimit == 0);
      if (++backtrack_count == backtrack_limit) {
        return static_cast<IrregexpInterpreter::Result>(return_code);
      }

      IrregexpInterpreter::Result result =
          HandleInterrupts(isolate, call_origin, code_array, subject_string,
                           &code_base, &subject, &pc);
      if (result != IrregexpInterpreter::SUCCESS) return result;

      SET_PC_FROM_OFFSET(backtrack_stack.pop());
      DISPATCH();
    }
    BYTECODE(PopRegister, register_index) {
      ADVANCE();
      registers[register_index] = backtrack_stack.pop();
      DISPATCH();
    }
    BYTECODE(Fail) {
      isolate->counters()->regexp_backtracks()->AddSample(
          static_cast<int>(backtrack_count));
      return IrregexpInterpreter::FAILURE;
    }
    BYTECODE(Succeed) {
      isolate->counters()->regexp_backtracks()->AddSample(
          static_cast<int>(backtrack_count));
      registers.CopyToOutputRegisters();
      return IrregexpInterpreter::SUCCESS;
    }
    BYTECODE(AdvanceCurrentPosition, by) {
      ADVANCE();
      ADVANCE_CURRENT_POSITION(by);
      DISPATCH();
    }
    BYTECODE(GoTo, label) {
      SET_PC_FROM_OFFSET(label);
      DISPATCH();
    }
    BYTECODE(AdvanceCpAndGoto, by, on_goto) {
      SET_PC_FROM_OFFSET(on_goto);
      ADVANCE_CURRENT_POSITION(by);
      DISPATCH();
    }
    BYTECODE(CheckFixedLengthLoop, on_tos_equals_current_position) {
      if (current == backtrack_stack.peek()) {
        SET_PC_FROM_OFFSET(on_tos_equals_current_position);
        backtrack_stack.pop();
      } else {
        ADVANCE();
      }
      DISPATCH();
    }
    BYTECODE(LoadCurrentCharacter, cp_offset, bounds_check_offset, on_failure) {
      if (!IndexIsInBounds(current + bounds_check_offset, subject.length())) {
        SET_PC_FROM_OFFSET(on_failure);
      } else {
        ADVANCE();
        current_char = subject[current + cp_offset];
      }
      DISPATCH();
    }
    BYTECODE(LoadCurrentCharacterUnchecked, cp_offset) {
      ADVANCE();
      int pos = current + cp_offset;
      current_char = subject[pos];
      DISPATCH();
    }
    BYTECODE(Load2CurrentChars, cp_offset, bounds_check_offset, on_failure) {
      if (!IndexIsInBounds(current + bounds_check_offset, subject.length())) {
        SET_PC_FROM_OFFSET(on_failure);
      } else {
        ADVANCE();
        current_char = Load2Characters(subject, current + cp_offset);
      }
      DISPATCH();
    }
    BYTECODE(Load2CurrentCharsUnchecked, cp_offset) {
      ADVANCE();
      int pos = current + cp_offset;
      current_char = Load2Characters(subject, pos);
      DISPATCH();
    }
    BYTECODE(Load4CurrentChars, cp_offset, bounds_check_offset, on_failure) {
      DCHECK_EQ(1, sizeof(Char));
      if (!IndexIsInBounds(current + bounds_check_offset, subject.length())) {
        SET_PC_FROM_OFFSET(on_failure);
      } else {
        ADVANCE();
        current_char = Load4Characters(subject, current + cp_offset);
      }
      DISPATCH();
    }
    BYTECODE(Load4CurrentCharsUnchecked, cp_offset) {
      ADVANCE();
      DCHECK_EQ(1, sizeof(Char));
      int pos = current + cp_offset;
      current_char = Load4Characters(subject, pos);
      DISPATCH();
    }
    BYTECODE(Check4Chars, characters, on_equal) {
      if (characters == current_char) {
        SET_PC_FROM_OFFSET(on_equal);
      } else {
        ADVANCE();
      }
      DISPATCH();
    }
    BYTECODE(CheckCharacter, character, on_equal) {
      if (character == current_char) {
        SET_PC_FROM_OFFSET(on_equal);
      } else {
        ADVANCE();
      }
      DISPATCH();
    }
    BYTECODE(CheckNot4Chars, characters, on_not_equal) {
      if (characters != current_char) {
        SET_PC_FROM_OFFSET(on_not_equal);
      } else {
        ADVANCE();
      }
      DISPATCH();
    }
    BYTECODE(CheckNotCharacter, character, on_not_equal) {
      if (character != current_char) {
        SET_PC_FROM_OFFSET(on_not_equal);
      } else {
        ADVANCE();
      }
      DISPATCH();
    }
    BYTECODE(AndCheck4Chars, characters, mask, on_equal) {
      if (characters == (current_char & mask)) {
        SET_PC_FROM_OFFSET(on_equal);
      } else {
        ADVANCE();
      }
      DISPATCH();
    }
    BYTECODE(CheckCharacterAfterAnd, character, mask, on_equal) {
      if (character == (current_char & mask)) {
        SET_PC_FROM_OFFSET(on_equal);
      } else {
        ADVANCE();
      }
      DISPATCH();
    }
    BYTECODE(AndCheckNot4Chars, characters, mask, on_not_equal) {
      if (characters != (current_char & mask)) {
        SET_PC_FROM_OFFSET(on_not_equal);
      } else {
        ADVANCE();
      }
      DISPATCH();
    }
    BYTECODE(CheckNotCharacterAfterAnd, character, mask, on_not_equal) {
      if (character != (current_char & mask)) {
        SET_PC_FROM_OFFSET(on_not_equal);
      } else {
        ADVANCE();
      }
      DISPATCH();
    }
    BYTECODE(CheckNotCharacterAfterMinusAnd, character, minus, mask,
             on_not_equal) {
      if (character != ((current_char - minus) & mask)) {
        SET_PC_FROM_OFFSET(on_not_equal);
      } else {
        ADVANCE();
      }
      DISPATCH();
    }
    BYTECODE(CheckCharacterInRange, from, to, on_in_range) {
      if (from <= current_char && current_char <= to) {
        SET_PC_FROM_OFFSET(on_in_range);
      } else {
        ADVANCE();
      }
      DISPATCH();
    }
    BYTECODE(CheckCharacterNotInRange, from, to, on_not_in_range) {
      if (from > current_char || current_char > to) {
        SET_PC_FROM_OFFSET(on_not_in_range);
      } else {
        ADVANCE();
      }
      DISPATCH();
    }
    BYTECODE(CheckBitInTable, on_bit_set, table) {
      if (CheckBitInTable(current_char, table)) {
        SET_PC_FROM_OFFSET(on_bit_set);
      } else {
        ADVANCE();
      }
      DISPATCH();
    }
    BYTECODE(CheckCharacterLT, limit, on_less) {
      if (current_char < limit) {
        SET_PC_FROM_OFFSET(on_less);
      } else {
        ADVANCE();
      }
      DISPATCH();
    }
    BYTECODE(CheckCharacterGT, limit, on_greater) {
      if (current_char > limit) {
        SET_PC_FROM_OFFSET(on_greater);
      } else {
        ADVANCE();
      }
      DISPATCH();
    }
    BYTECODE(IfRegisterLT, register_index, comparand, on_less_than) {
      if (registers[register_index] < comparand) {
        SET_PC_FROM_OFFSET(on_less_than);
      } else {
        ADVANCE();
      }
      DISPATCH();
    }
    BYTECODE(IfRegisterGE, register_index, comparand, on_greater_or_equal) {
      if (registers[register_index] >= comparand) {
        SET_PC_FROM_OFFSET(on_greater_or_equal);
      } else {
        ADVANCE();
      }
      DISPATCH();
    }
    BYTECODE(IfRegisterEqPos, register_index, on_eq) {
      if (registers[register_index] == current) {
        SET_PC_FROM_OFFSET(on_eq);
      } else {
        ADVANCE();
      }
      DISPATCH();
    }
    BYTECODE(CheckNotBackRef, start_reg, on_not_equal) {
      int from = registers[start_reg];
      int len = registers[start_reg + 1] - from;
      if (from >= 0 && len > 0) {
        if (current + len > subject.length() ||
            !CompareCharsEqual(&subject[from], &subject[current], len)) {
          SET_PC_FROM_OFFSET(on_not_equal);
          DISPATCH();
        }
        ADVANCE_CURRENT_POSITION(len);
      }
      ADVANCE();
      DISPATCH();
    }
    BYTECODE(CheckNotBackRefBackward, start_reg, on_not_equal) {
      int from = registers[start_reg];
      int len = registers[start_reg + 1] - from;
      if (from >= 0 && len > 0) {
        if (current - len < 0 ||
            !CompareCharsEqual(&subject[from], &subject[current - len], len)) {
          SET_PC_FROM_OFFSET(on_not_equal);
          DISPATCH();
        }
        SET_CURRENT_POSITION(current - len);
      }
      ADVANCE();
      DISPATCH();
    }
    BYTECODE(CheckNotBackRefNoCaseUnicode, start_reg, on_not_equal) {
      int from = registers[start_reg];
      int len = registers[start_reg + 1] - from;
      if (from >= 0 && len > 0) {
        if (current + len > subject.length() ||
            !BackRefMatchesNoCase(isolate, from, current, len, subject, true)) {
          SET_PC_FROM_OFFSET(on_not_equal);
          DISPATCH();
        }
        ADVANCE_CURRENT_POSITION(len);
      }
      ADVANCE();
      DISPATCH();
    }
    BYTECODE(CheckNotBackRefNoCase, start_reg, on_not_equal) {
      int from = registers[start_reg];
      int len = registers[start_reg + 1] - from;
      if (from >= 0 && len > 0) {
        if (current + len > subject.length() ||
            !BackRefMatchesNoCase(isolate, from, current, len, subject,
                                  false)) {
          SET_PC_FROM_OFFSET(on_not_equal);
          DISPATCH();
        }
        ADVANCE_CURRENT_POSITION(len);
      }
      ADVANCE();
      DISPATCH();
    }
    BYTECODE(CheckNotBackRefNoCaseUnicodeBackward, start_reg, on_not_equal) {
      int from = registers[start_reg];
      int len = registers[start_reg + 1] - from;
      if (from >= 0 && len > 0) {
        if (current - len < 0 ||
            !BackRefMatchesNoCase(isolate, from, current - len, len, subject,
                                  true)) {
          SET_PC_FROM_OFFSET(on_not_equal);
          DISPATCH();
        }
        SET_CURRENT_POSITION(current - len);
      }
      ADVANCE();
      DISPATCH();
    }
    BYTECODE(CheckNotBackRefNoCaseBackward, start_reg, on_not_equal) {
      int from = registers[start_reg];
      int len = registers[start_reg + 1] - from;
      if (from >= 0 && len > 0) {
        if (current - len < 0 ||
            !BackRefMatchesNoCase(isolate, from, current - len, len, subject,
                                  false)) {
          SET_PC_FROM_OFFSET(on_not_equal);
          DISPATCH();
        }
        SET_CURRENT_POSITION(current - len);
      }
      ADVANCE();
      DISPATCH();
    }
    BYTECODE(CheckAtStart, cp_offset, on_at_start) {
      if (current + cp_offset == 0) {
        SET_PC_FROM_OFFSET(on_at_start);
      } else {
        ADVANCE();
      }
      DISPATCH();
    }
    BYTECODE(CheckNotAtStart, cp_offset, on_not_at_start) {
      if (current + cp_offset == 0) {
        ADVANCE();
      } else {
        SET_PC_FROM_OFFSET(on_not_at_start);
      }
      DISPATCH();
    }
    BYTECODE(SetCurrentPositionFromEnd, by) {
      ADVANCE();
      if (subject.length() - current > by) {
        SET_CURRENT_POSITION(subject.length() - by);
        current_char = subject[current - 1];
      }
      DISPATCH();
    }
    BYTECODE(CheckPosition, cp_offset, on_failure) {
      int pos = current + cp_offset;
      if (pos >= subject.length() || pos < 0) {
        SET_PC_FROM_OFFSET(on_failure);
      } else {
        ADVANCE();
      }
      DISPATCH();
    }
    BYTECODE(CheckSpecialClassRanges, character_set, on_no_match) {
      const bool match =
          CheckSpecialClassRanges<Char>(current_char, character_set);
      if (match) {
        ADVANCE();
      } else {
        SET_PC_FROM_OFFSET(on_no_match);
      }
      DISPATCH();
    }
    BYTECODE(SkipUntilChar, cp_offset, advance_by, character,
             bounds_check_offset, on_match, on_no_match) {
      while (IndexIsInBounds(current + bounds_check_offset, subject.length())) {
        current_char = subject[current + cp_offset];
        if (character == current_char) {
          SET_PC_FROM_OFFSET(on_match);
          DISPATCH();
        }
        ADVANCE_CURRENT_POSITION(advance_by);
      }
      SET_PC_FROM_OFFSET(on_no_match);
      DISPATCH();
    }
    BYTECODE(SkipUntilCharAnd, cp_offset, advance_by, character, mask,
             bounds_check_offset, on_match, on_no_match) {
      while (IndexIsInBounds(current + bounds_check_offset, subject.length())) {
        current_char = subject[current + cp_offset];
        if (character == (current_char & mask)) {
          SET_PC_FROM_OFFSET(on_match);
          DISPATCH();
        }
        ADVANCE_CURRENT_POSITION(advance_by);
      }
      SET_PC_FROM_OFFSET(on_no_match);
      DISPATCH();
    }
    BYTECODE(SkipUntilBitInTable, cp_offset, advance_by, table,
             bounds_check_offset, on_match, on_no_match) {
      while (IndexIsInBounds(current + bounds_check_offset, subject.length())) {
        current_char = subject[current + cp_offset];
        if (CheckBitInTable(current_char, table)) {
          SET_PC_FROM_OFFSET(on_match);
          DISPATCH();
        }
        ADVANCE_CURRENT_POSITION(advance_by);
      }
      SET_PC_FROM_OFFSET(on_no_match);
      DISPATCH();
    }
    BYTECODE(SkipUntilGtOrNotBitInTable, cp_offset, advance_by, character,
             table, bounds_check_offset, on_match, on_no_match) {
      while (IndexIsInBounds(current + bounds_check_offset, subject.length())) {
        current_char = subject[current + cp_offset];
        if (current_char > character) {
          SET_PC_FROM_OFFSET(on_match);
          DISPATCH();
        }
        if (!CheckBitInTable(current_char, table)) {
          SET_PC_FROM_OFFSET(on_match);
          DISPATCH();
        }
        ADVANCE_CURRENT_POSITION(advance_by);
      }
      SET_PC_FROM_OFFSET(on_no_match);
      DISPATCH();
    }
    BYTECODE(SkipUntilCharOrChar, cp_offset, advance_by, char1, char2,
             bounds_check_offset, on_match, on_no_match) {
      while (IndexIsInBounds(current + bounds_check_offset, subject.length())) {
        current_char = subject[current + cp_offset];
        // The two if-statements below are split up intentionally, as combining
        // them seems to result in register allocation behaving quite
        // differently and slowing down the resulting code.
        if (char1 == current_char) {
          SET_PC_FROM_OFFSET(on_match);
          DISPATCH();
        }
        if (char2 == current_char) {
          SET_PC_FROM_OFFSET(on_match);
          DISPATCH();
        }
        ADVANCE_CURRENT_POSITION(advance_by);
      }
      SET_PC_FROM_OFFSET(on_no_match);
      DISPATCH();
    }
    BYTECODE(SkipUntilOneOfMasked, cp_offset, advance_by, both_chars, both_mask,
             max_offset, chars1, mask1, chars2, mask2, on_match1, on_match2,
             on_failure) {
      DCHECK_GE(cp_offset, 0);
      DCHECK_GE(max_offset, cp_offset + 3);
      // We should only get here in 1-byte mode.
      DCHECK_EQ(1, sizeof(Char));
      while (IndexIsInBounds(current + max_offset, subject.length())) {
        int pos = current + cp_offset;
        current_char = Load4Characters(subject, pos);
        if (both_chars == (current_char & both_mask)) {
          if (chars1 == (current_char & mask1)) {
            SET_PC_FROM_OFFSET(on_match1);
            DISPATCH();
          }
          if (chars2 == (current_char & mask2)) {
            SET_PC_FROM_OFFSET(on_match2);
            DISPATCH();
          }
        }
        ADVANCE_CURRENT_POSITION(advance_by);
      }
      SET_PC_FROM_OFFSET(on_failure);
      DISPATCH();
    }
    BYTECODE(SkipUntilOneOfMasked3, bc0_cp_offset, bc0_advance_by, bc0_table,
             bc1_bounds_check_offset, bc1_on_failure, bc1_cp_offset,
             bc2_characters, bc2_mask, bc3_by, bc4_bounds_check_offset,
             bc4_cp_offset, bc5_characters, bc5_mask, bc5_on_equal,
             bc6_characters, bc6_mask, bc6_on_equal, bc7_characters, bc7_mask,
             fallthrough_jump_target) {
      // We should only get here in 1-byte mode.
      DCHECK_EQ(1, sizeof(Char));

      while (true) {
        // bc0: kSkipUntilBitInTable
        // on_match and on_no_match are constrained to jump to bc1.
        while (IndexIsInBounds(current + bc0_cp_offset, subject.length())) {
          current_char = subject[current + bc0_cp_offset];
          if (CheckBitInTable(current_char, bc0_table)) {
            break;
          }
          ADVANCE_CURRENT_POSITION(bc0_advance_by);
        }

        // bc1: kLoad4CurrentChars
        if (!IndexIsInBounds(current + bc1_bounds_check_offset,
                             subject.length())) {
          SET_PC_FROM_OFFSET(bc1_on_failure);
          DISPATCH();
        }

        // Load 4 characters
        int pos = current + bc1_cp_offset;
        current_char = Load4Characters(subject, pos);

        // bc2: AndCheck4Chars
        // on_equal is constrained to jump to bc4.
        if (bc2_characters == (current_char & bc2_mask)) {
          // bc4: Load4CurrentChars
          // on_failure is constrained to jump to bc3 (AdvanceCpAndGoto).
          if (!IndexIsInBounds(current + bc4_bounds_check_offset,
                               subject.length())) {
            // bc3: AdvanceCpAndGoto
            // on_goto is constrained to jump back to bc0.
            ADVANCE_CURRENT_POSITION(bc3_by);
            continue;
          }
          // TODO(jgruber): Usually we can reuse some of the bytes loaded above.
          pos = current + bc4_cp_offset;
          current_char = Load4Characters(subject, pos);

          // bc5: AndCheck4Chars
          if (bc5_characters == (current_char & bc5_mask)) {
            SET_PC_FROM_OFFSET(bc5_on_equal);
            DISPATCH();
          }
          // bc6: AndCheck4Chars
          if (bc6_characters == (current_char & bc6_mask)) {
            SET_PC_FROM_OFFSET(bc6_on_equal);
            DISPATCH();
          }
          // bc7: AndCheckNot4Chars
          // on_not_equal is constrained to jump to bc3.
          if (bc7_characters == (current_char & bc7_mask)) {
            SET_PC_FROM_OFFSET(fallthrough_jump_target);
            DISPATCH();
          }
        }

        // bc3: AdvanceCpAndGoto
        // on_goto is constrained to jump back to bc0.
        ADVANCE_CURRENT_POSITION(bc3_by);
      }

      UNREACHABLE();
    }
    BYTECODES_END()
#if V8_USE_COMPUTED_GOTO
// Lint gets confused a lot if we just use !V8_USE_COMPUTED_GOTO or ifndef
// V8_USE_COMPUTED_GOTO here.
#else
      default:
        UNREACHABLE();
    }
  // Label we jump to in DISPATCH(). There must be no instructions between the
  // end of the switch, this label and the end of the loop.
  switch_dispatch_continuation : {}
#endif  // V8_USE_COMPUTED_GOTO
  }
}

Tree* ParserImpl<CharT, mode>::ParseDisjunction() {
  DRPERF_BENCH_REGION("v8-regexp-006");
  // Used to store current state while parsing subexpressions.
  ParserState<mode> initial_state(nullptr, INITIAL, Lookaround::LOOKAHEAD, 0,
                                  nullptr, flags(), zone());
  ParserState<mode>* state = &initial_state;
  // Cache the builder in a local variable for quick access.
  Builder<mode>* builder = initial_state.builder();
  while (true) {
    switch (current()) {
      case kEndMarker:
        if (failed()) return nullptr;  // E.g. the initial Advance failed.
        if (state->IsSubexpression()) {
          // Inside a parenthesized group when hitting end of input.
          return ReportError(Error::kUnterminatedGroup);
        }
        DCHECK_EQ(INITIAL, state->group_type());
        // Parsing completed successfully.
        return builder->ToRegExp();
      case ')': {
        if (!state->IsSubexpression()) {
          return ReportError(Error::kUnmatchedParen);
        }
        DCHECK_NE(INITIAL, state->group_type());

        Advance();
        // End disjunction parsing and convert builder content to new single
        // regexp atom.
        Tree* body = builder->ToRegExp();

        int end_capture_index = captures_started();

        int capture_index = state->capture_index();
        SubexpressionType group_type = state->group_type();

        // Build result of subexpression.
        if (group_type == CAPTURE) {
          if (state->IsNamedCapture()) {
            CreateNamedCaptureAtIndex(state, capture_index CHECK_FAILED);
          }
          if constexpr (mode == ParseMode::kBuildAST) {
            Capture* capture = GetCapture(capture_index);
            capture->set_body(body);
            body = capture;
          }
        } else if (group_type == GROUPING) {
          if constexpr (mode == ParseMode::kBuildAST) {
            body = zone()->template New<Group>(body, builder->flags());
          }
        } else {
          DCHECK(group_type == POSITIVE_LOOKAROUND ||
                 group_type == NEGATIVE_LOOKAROUND);
          if constexpr (mode == ParseMode::kBuildAST) {
            bool is_positive = (group_type == POSITIVE_LOOKAROUND);
            body = zone()->template New<Lookaround>(
                body, is_positive, end_capture_index - capture_index,
                capture_index, state->lookaround_type(), lookaround_count_);
          }
          lookaround_count_++;
        }

        // Restore previous state.
        Lookaround::Type prev_lookaround_type = state->lookaround_type();
        state = state->previous_state();
        builder = state->builder();
        flags_ = builder->flags();

        if constexpr (mode == ParseMode::kBuildAST) {
          builder->AddAtom(body);
        } else {
          // Lookarounds need special treatment in VerifySyntax node to enforce
          // quantifier restrictions on lookaround assertions (without having an
          // AST). See Builder<ParseMode::kVerifySyntax>::AddQuantifierToAtom.
          if (group_type == POSITIVE_LOOKAROUND ||
              group_type == NEGATIVE_LOOKAROUND) {
            builder->AddLookaround(prev_lookaround_type);
          } else {
            builder->AddAtom(nullptr);
          }
        }
        // For compatibility with JSC and ES3, we allow quantifiers after
        // lookaheads, and break in all cases.
        break;
      }
      case '|': {
        Advance();
        state->NewAlternative(captures_started());
        builder->NewAlternative();
        continue;
      }
      case '*':
      case '+':
      case '?':
        return ReportError(Error::kNothingToRepeat);
      case '^': {
        Advance();
        Assertion* assertion = nullptr;
        if constexpr (mode == ParseMode::kBuildAST) {
          assertion = zone()->template New<Assertion>(
              builder->multiline() ? Assertion::Type::START_OF_LINE
                                   : Assertion::Type::START_OF_INPUT);
        }
        builder->AddAssertion(assertion);
        set_contains_anchor();
        continue;
      }
      case '$': {
        Advance();
        Assertion* assertion = nullptr;
        if constexpr (mode == ParseMode::kBuildAST) {
          Assertion::Type assertion_type = builder->multiline()
                                               ? Assertion::Type::END_OF_LINE
                                               : Assertion::Type::END_OF_INPUT;
          assertion = zone()->template New<Assertion>(assertion_type);
        }
        builder->AddAssertion(assertion);
        continue;
      }
      case '.': {
        Advance();
        ZoneList<CharacterRange>* ranges = nullptr;
        if constexpr (mode == ParseMode::kBuildAST) {
          ranges = zone()->template New<ZoneList<CharacterRange>>(2, zone());
        }

        if (builder->dotall()) {
          // Everything.
          if constexpr (mode == ParseMode::kBuildAST) {
            CharacterRange::AddClassEscape(StandardCharacterSet::kEverything,
                                           ranges, false, zone());
          }
        } else {
          // Everything except \x0A, \x0D, \u2028 and \u2029.
          if constexpr (mode == ParseMode::kBuildAST) {
            CharacterRange::AddClassEscape(
                StandardCharacterSet::kNotLineTerminator, ranges, false,
                zone());
          }
        }

        ClassRanges* cc = nullptr;
        if constexpr (mode == ParseMode::kBuildAST) {
          cc = zone()->template New<ClassRanges>(zone(), ranges);
        }
        builder->AddClassRanges(cc);
        break;
      }
      case '(': {
        state = ParseOpenParenthesis(state CHECK_FAILED);
        builder = state->builder();
        flags_ = builder->flags();
        continue;
      }
      case '[': {
        ClassSetResult<mode> cc = ParseCharacterClass(builder CHECK_FAILED);
        if constexpr (mode == ParseMode::kBuildAST) {
          if (cc.tree->IsClassRanges()) {
            builder->AddClassRanges(cc.tree->AsClassRanges());
          } else {
            DCHECK(cc.tree->IsClassSetExpression());
            builder->AddTerm(cc.tree);
          }
        } else {
          builder->AddClassRanges(nullptr);
        }
        break;
      }
      // Atom ::
      //   \ AtomEscape
      case '\\': {
        const base::uc32 escaped_char = Next();
        if (v8_flags.js_regexp_buffer_boundaries && IsUnicodeMode()) {
          bool is_buffer_boundary_assertion = true;
          Assertion::Type assertion_type = Assertion::Type::START_OF_INPUT;
          switch (escaped_char) {
            // Assertion ::
            //   [+UnicodeMode] \A
            //   [+UnicodeMode] \z
            //   [+UnicodeMode] \Z
            case 'A':
              assertion_type = Assertion::Type::START_OF_INPUT;
              set_contains_anchor();
              break;
            case 'z':
              assertion_type = Assertion::Type::END_OF_INPUT;
              break;
            case 'Z':
              assertion_type = Assertion::Type::END_OF_BUFFER;
              break;
            default:
              is_buffer_boundary_assertion = false;
              break;
          }
          if (is_buffer_boundary_assertion) {
            Advance(2);
            Assertion* assertion = nullptr;
            if constexpr (mode == ParseMode::kBuildAST) {
              assertion = zone()->template New<Assertion>(assertion_type);
            }
            builder->AddAssertion(assertion);
            continue;
          }
        }

        switch (escaped_char) {
          case kEndMarker:
            return ReportError(Error::kEscapeAtEndOfPattern);
          // AtomEscape ::
          //   [+UnicodeMode] DecimalEscape
          //   [~UnicodeMode] DecimalEscape but only if the CapturingGroupNumber
          //                  of DecimalEscape is ≤ NcapturingParens
          //   CharacterEscape (some cases of this mixed in too)
          //
          // TODO(jgruber): It may make sense to disentangle all the different
          // cases and make the structure mirror the spec, e.g. for AtomEscape:
          //
          //  if (TryParseDecimalEscape(...)) return;
          //  if (TryParseCharacterClassEscape(...)) return;
          //  if (TryParseCharacterEscape(...)) return;
          //  if (TryParseGroupName(...)) return;
          case '1':
          case '2':
          case '3':
          case '4':
          case '5':
          case '6':
          case '7':
          case '8':
          case '9': {
            int index = 0;
            const bool is_backref =
                ParseBackReferenceIndex(&index CHECK_FAILED);
            if (is_backref) {
              if (state->IsInsideCaptureGroup(index)) {
                // The back reference is inside the capture group it refers to.
                // Nothing can possibly have been captured yet, so we use empty
                // instead. This ensures that, when checking a back reference,
                // the capture registers of the referenced capture are either
                // both set or both cleared.
                builder->AddEmpty();
              } else {
                Tree* atom = nullptr;
                if constexpr (mode == ParseMode::kBuildAST) {
                  Capture* capture = GetCapture(index);
                  atom = zone()->template New<BackReference>(capture, zone());
                }
                builder->AddAtom(atom);
              }
              break;
            }
            // With /u and /v, no identity escapes except for syntax characters
            // are allowed. Otherwise, all identity escapes are allowed.
            if (IsUnicodeMode()) {
              return ReportError(Error::kInvalidEscape);
            }
            base::uc32 first_digit = Next();
            if (first_digit == '8' || first_digit == '9') {
              builder->AddCharacter(first_digit);
              Advance(2);
              break;
            }
            [[fallthrough]];
          }
          case '0': {
            Advance();
            if (IsUnicodeMode() && Next() >= '0' && Next() <= '9') {
              // Decimal escape with leading 0 are not parsed as octal.
              return ReportError(Error::kInvalidDecimalEscape);
            }
            base::uc32 octal = ParseOctalLiteral();
            builder->AddCharacter(octal);
            break;
          }
          case 'b': {
            Advance(2);
            Assertion* assertion = nullptr;
            if constexpr (mode == ParseMode::kBuildAST) {
              assertion =
                  zone()->template New<Assertion>(Assertion::Type::BOUNDARY);
            }
            builder->AddAssertion(assertion);
            continue;
          }
          case 'B': {
            Advance(2);
            Assertion* assertion = nullptr;
            if constexpr (mode == ParseMode::kBuildAST) {
              assertion = zone()->template New<Assertion>(
                  Assertion::Type::NON_BOUNDARY);
            }
            builder->AddAssertion(assertion);
            continue;
          }
          // AtomEscape ::
          //   CharacterClassEscape
          case 'd':
          case 'D':
          case 's':
          case 'S':
          case 'w':
          case 'W': {
            base::uc32 next = Next();
            ZoneList<CharacterRange>* ranges = nullptr;
            if constexpr (mode == ParseMode::kBuildAST) {
              ranges =
                  zone()->template New<ZoneList<CharacterRange>>(2, zone());
            }
            ClassSetResult<mode> parsed_character_class_escape =
                TryParseCharacterClassEscape(
                    next, InClassEscapeState::kNotInClass, ranges, nullptr,
                    zone(), add_unicode_case_equivalents() CHECK_FAILED);

            if (parsed_character_class_escape.success) {
              ClassRanges* cc = nullptr;
              if constexpr (mode == ParseMode::kBuildAST) {
                cc = zone()->template New<ClassRanges>(zone(), ranges);
              }
              builder->AddClassRanges(cc);
            } else {
              CHECK(!IsUnicodeMode());
              Advance(2);
              builder->AddCharacter(next);  // IdentityEscape.
            }
            break;
          }
          case 'p':
          case 'P': {
            base::uc32 next = Next();
            ZoneList<CharacterRange>* ranges = nullptr;
            if constexpr (mode == ParseMode::kBuildAST) {
              ranges =
                  zone()->template New<ZoneList<CharacterRange>>(2, zone());
            }
            CharacterClassStrings* strings = nullptr;
            if constexpr (mode == ParseMode::kBuildAST) {
              if (unicode_sets()) {
                strings = zone()->template New<CharacterClassStrings>(zone());
              }
            }
            ClassSetResult<mode> parsed_character_class_escape =
                TryParseCharacterClassEscape(
                    next, InClassEscapeState::kNotInClass, ranges, strings,
                    zone(), add_unicode_case_equivalents() CHECK_FAILED);

            if (parsed_character_class_escape.success) {
              Tree* term = nullptr;
              if constexpr (mode == ParseMode::kBuildAST) {
                if (unicode_sets()) {
                  term = zone()->template New<ClassSetOperand>(ranges, strings);
                } else {
                  term = zone()->template New<ClassRanges>(zone(), ranges);
                }
              }
              builder->AddTerm(term);
            } else {
              CHECK(!IsUnicodeMode());
              Advance(2);
              builder->AddCharacter(next);  // IdentityEscape.
            }
            break;
          }
          // AtomEscape ::
          //   k GroupName
          case 'k': {
            // Either an identity escape or a named back-reference.  The two
            // interpretations are mutually exclusive: '\k' is interpreted as
            // an identity escape for non-Unicode patterns without named
            // capture groups, and as the beginning of a named back-reference
            // in all other cases.
            const bool has_named_captures =
                HasNamedCaptures(InClassEscapeState::kNotInClass CHECK_FAILED);
            if (IsUnicodeMode() || has_named_captures) {
              Advance(2);
              ParseNamedBackReference(builder, state CHECK_FAILED);
              break;
            }
          }
            [[fallthrough]];
          // AtomEscape ::
          //   CharacterEscape
          default: {
            bool is_escaped_unicode_character = false;
            base::uc32 c = ParseCharacterEscape(
                InClassEscapeState::kNotInClass,
                &is_escaped_unicode_character CHECK_FAILED);
            if (is_escaped_unicode_character) {
              builder->AddEscapedUnicodeCharacter(c);
            } else {
              builder->AddCharacter(c);
            }
            break;
          }
        }
        break;
      }
      case '{': {
        int dummy;
        bool parsed = ParseIntervalQuantifier(&dummy, &dummy CHECK_FAILED);
        if (parsed) return ReportError(Error::kNothingToRepeat);
        [[fallthrough]];
      }
      case '}':
      case ']':
        if (IsUnicodeMode()) {
          return ReportError(Error::kLoneQuantifierBrackets);
        }
        [[fallthrough]];
      default:
        builder->AddUnicodeCharacter(current());
        Advance();
        break;
    }  // end switch(current())

    int min;
    int max;
    switch (current()) {
      // QuantifierPrefix ::
      //   *
      //   +
      //   ?
      //   {
      case '*':
        min = 0;
        max = Tree::kInfinity;
        Advance();
        break;
      case '+':
        min = 1;
        max = Tree::kInfinity;
        Advance();
        break;
      case '?':
        min = 0;
        max = 1;
        Advance();
        break;
      case '{':
        if (ParseIntervalQuantifier(&min, &max)) {
          if (max < min) {
            return ReportError(Error::kRangeOutOfOrder);
          }
          break;
        } else if (IsUnicodeMode()) {
          // Incomplete quantifiers are not allowed.
          return ReportError(Error::kIncompleteQuantifier);
        }
        continue;
      default:
        continue;
    }
    Quantifier::QuantifierType quantifier_type = Quantifier::GREEDY;
    if (current() == '?') {
      quantifier_type = Quantifier::NON_GREEDY;
      Advance();
    } else if (v8_flags.regexp_possessive_quantifier && current() == '+') {
      // v8_flags.regexp_possessive_quantifier is a debug-only flag.
      quantifier_type = Quantifier::POSSESSIVE;
      Advance();
    }
    if (!builder->AddQuantifierToAtom(min, max, quantifier_count_,
                                      quantifier_type)) {
      return ReportError(Error::kInvalidQuantifier);
    }
    ++quantifier_count_;
  }
}

void ParserImpl<CharT, mode>::ScanForCaptures(
    InClassEscapeState in_class_escape_state) {
  DRPERF_BENCH_REGION("v8-regexp-007");
  DCHECK(!is_scanned_for_captures_);
  const int saved_position = position();
  // Start with captures started previous to current position
  int capture_count = captures_started();
  // When we start inside a character class, skip everything inside the class.
  if (in_class_escape_state == InClassEscapeState::kInClass) {
    // \k is always invalid within a class in unicode mode, thus we should never
    // call ScanForCaptures within a class.
    DCHECK(!IsUnicodeMode());
    int c;
    while ((c = current()) != kEndMarker) {
      Advance();
      if (c == '\\') {
        Advance();
      } else {
        if (c == ']') break;
      }
    }
  }
  // Add count of captures after this position.
  int n;
  while ((n = current()) != kEndMarker) {
    Advance();
    switch (n) {
      case '\\':
        Advance();
        break;
      case '[': {
        int class_nest_level = 0;
        int c;
        while ((c = current()) != kEndMarker) {
          Advance();
          if (c == '\\') {
            Advance();
          } else if (c == '[') {
            // With /v, '[' inside a class is treated as a nested class.
            // Without /v, '[' is a normal character.
            if (unicode_sets()) class_nest_level++;
          } else if (c == ']') {
            if (class_nest_level == 0) break;
            class_nest_level--;
          }
        }
        break;
      }
      case '(':
        if (current() == '?') {
          // At this point we could be in
          // * a non-capturing group '(:',
          // * a lookbehind assertion '(?<=' '(?<!'
          // * or a named capture '(?<'.
          //
          // Of these, only named captures are capturing groups.

          Advance();
          if (current() != '<') break;

          Advance();
          if (current() == '=' || current() == '!') break;

          // Found a possible named capture. It could turn out to be a syntax
          // error (e.g. an unterminated or invalid name), but that distinction
          // does not matter for our purposes.
          has_named_captures_ = true;
        }
        capture_count++;
        break;
    }
  }
  capture_count_ = capture_count;
  is_scanned_for_captures_ = true;
  Reset(saved_position);
}

const ZoneVector<base::uc16>* ParserImpl<CharT, mode>::ParseCaptureGroupName() {
  DRPERF_BENCH_REGION("v8-regexp-008");
  // Due to special Advance requirements (see the next comment), rewind by one
  // such that names starting with a surrogate pair are parsed correctly for
  // patterns where the unicode flag is unset.
  //
  // Note that we use this odd pattern of rewinding the last advance in order
  // to adhere to the common parser behavior of expecting `current` to point at
  // the first candidate character for a function (e.g. when entering ParseFoo,
  // `current` should point at the first character of Foo).
  RewindByOneCodepoint();

  ZoneVector<base::uc16>* name =
      zone()->template New<ZoneVector<base::uc16>>(zone());

  {
    // Advance behavior inside this function is tricky since
    // RegExpIdentifierName explicitly enables unicode (in spec terms, sets +U)
    // and thus allows surrogate pairs and \u{}-style escapes even in
    // non-unicode patterns. Therefore Advance within the capture group name
    // has to force-enable unicode, and outside the name revert to default
    // behavior.
    ForceUnicodeScope force_unicode(this);

    bool at_start = true;
    while (true) {
      Advance();
      base::uc32 c = current();

      // Convert unicode escapes.
      if (c == '\\' && Next() == 'u') {
        Advance(2);
        if (!ParseUnicodeEscape(&c)) {
          ReportError(Error::kInvalidUnicodeEscape);
          return nullptr;
        }
        RewindByOneCodepoint();
      }

      // The backslash char is misclassified as both ID_Start and ID_Continue.
      if (c == '\\') {
        ReportError(Error::kInvalidCaptureGroupName);
        return nullptr;
      }

      if (at_start) {
        if (!IsIdentifierStart(c)) {
          ReportError(Error::kInvalidCaptureGroupName);
          return nullptr;
        }
        push_code_unit(name, c);
        at_start = false;
      } else {
        if (c == '>') {
          break;
        } else if (IsIdentifierPart(c)) {
          push_code_unit(name, c);
        } else {
          ReportError(Error::kInvalidCaptureGroupName);
          return nullptr;
        }
      }
    }
  }

  // This final advance goes back into the state of pointing at the next
  // relevant char, which the rest of the parser expects. See also the previous
  // comments in this function.
  Advance();
  return name;
}

void ParserImpl<CharT, mode>::PatchNamedBackReferences() {
  DRPERF_BENCH_REGION("v8-regexp-009");
  if (named_back_references_ == nullptr) return;

  if (named_captures_ == nullptr) {
    ReportError(Error::kInvalidNamedCaptureReference);
    return;
  }

  // Look up and patch the actual capture for each named back reference.

  for (int i = 0; i < named_back_references_->length(); i++) {
    BackReference* ref = named_back_references_->at(i);

    // Capture used to search the named_captures_ by name, index of the
    // capture is never used.
    static const int kInvalidIndex = 0;
    Capture* search_capture = zone()->template New<Capture>(kInvalidIndex);
    DCHECK_NULL(search_capture->name());
    search_capture->set_name(ref->name());

    const auto& capture_it = named_captures_->find(search_capture);
    if (capture_it == named_captures_->end()) {
      ReportError(Error::kInvalidNamedCaptureReference);
      return;
    }

    if constexpr (mode == ParseMode::kBuildAST) {
      for (int index : *capture_it->second) {
        ref->add_capture(GetCapture(index), zone());
      }
    }
  }
}

bool ParserImpl<CharT, mode>::ParseIntervalQuantifier(int* min_out,
                                                      int* max_out) {
  DRPERF_BENCH_REGION("v8-regexp-010");
  DCHECK_EQ(current(), '{');
  int start = position();
  Advance();
  int min = 0;
  if (!IsDecimalDigit(current())) {
    Reset(start);
    return false;
  }
  while (IsDecimalDigit(current())) {
    int next = current() - '0';
    if (min > (Tree::kInfinity - next) / 10) {
      // Overflow. Skip past remaining decimal digits and return -1.
      do {
        Advance();
      } while (IsDecimalDigit(current()));
      min = Tree::kInfinity;
      break;
    }
    min = 10 * min + next;
    Advance();
  }
  int max = 0;
  if (current() == '}') {
    max = min;
    Advance();
  } else if (current() == ',') {
    Advance();
    if (current() == '}') {
      max = Tree::kInfinity;
      Advance();
    } else {
      while (IsDecimalDigit(current())) {
        int next = current() - '0';
        if (max > (Tree::kInfinity - next) / 10) {
          do {
            Advance();
          } while (IsDecimalDigit(current()));
          max = Tree::kInfinity;
          break;
        }
        max = 10 * max + next;
        Advance();
      }
      if (current() != '}') {
        Reset(start);
        return false;
      }
      Advance();
    }
  } else {
    Reset(start);
    return false;
  }
  *min_out = min;
  *max_out = max;
  return true;
}

bool ParserImpl<CharT, mode>::ParseUnicodeEscape(base::uc32* value) {
  DRPERF_BENCH_REGION("v8-regexp-011");
  // Accept both \uxxxx and \u{xxxxxx} (if harmony unicode escapes are
  // allowed). In the latter case, the number of hex digits between { } is
  // arbitrary. \ and u have already been read.
  if (current() == '{' && IsUnicodeMode()) {
    int start = position();
    Advance();
    if (ParseUnlimitedLengthHexNumber(0x10FFFF, value)) {
      if (current() == '}') {
        Advance();
        return true;
      }
    }
    Reset(start);
    return false;
  }
  // \u but no {, or \u{...} escapes not allowed.
  bool result = ParseHexEscape(4, value);
  if (result && IsUnicodeMode() && unibrow::Utf16::IsLeadSurrogate(*value) &&
      current() == '\\') {
    // Attempt to read trail surrogate.
    int start = position();
    if (Next() == 'u') {
      Advance(2);
      base::uc32 trail;
      if (ParseHexEscape(4, &trail) &&
          unibrow::Utf16::IsTrailSurrogate(trail)) {
        *value = unibrow::Utf16::CombineSurrogatePair(
            static_cast<base::uc16>(*value), static_cast<base::uc16>(trail));
        return true;
      }
    }
    Reset(start);
  }
  return result;
}

bool ParserImpl<CharT, mode>::ParsePropertyClassName(ZoneVector<char>* name_1,
                                                     ZoneVector<char>* name_2) {
  DRPERF_BENCH_REGION("v8-regexp-012");
  DCHECK(name_1->empty());
  DCHECK(name_2->empty());
  // Parse the property class as follows:
  // - In \p{name}, 'name' is interpreted
  //   - either as a general category property value name.
  //   - or as a binary property name.
  // - In \p{name=value}, 'name' is interpreted as an enumerated property name,
  //   and 'value' is interpreted as one of the available property value names.
  // - Aliases in PropertyAlias.txt and PropertyValueAlias.txt can be used.
  // - Loose matching is not applied.
  if (current() == '{') {
    // Parse \p{[PropertyName=]PropertyNameValue}
    for (Advance(); current() != '}' && current() != '='; Advance()) {
      if (!IsUnicodePropertyValueCharacter(current())) return false;
      if (!has_next()) return false;
      name_1->push_back(static_cast<char>(current()));
    }
    if (current() == '=') {
      for (Advance(); current() != '}'; Advance()) {
        if (!IsUnicodePropertyValueCharacter(current())) return false;
        if (!has_next()) return false;
        name_2->push_back(static_cast<char>(current()));
      }
      name_2->push_back(0);  // null-terminate string.
    }
  } else {
    return false;
  }
  Advance();
  name_1->push_back(0);  // null-terminate string.

  DCHECK(name_1->size() - 1 == std::strlen(name_1->data()));
  DCHECK(name_2->empty() || name_2->size() - 1 == std::strlen(name_2->data()));
  return true;
}

Tree* ParserImpl<CharT, mode>::ParseClassRanges(
    ZoneList<CharacterRange>* ranges, bool add_unicode_case_equivalents) {
  DRPERF_BENCH_REGION("v8-regexp-013");
  base::uc32 char_1, char_2;
  bool is_class_1, is_class_2;
  while (has_more() && current() != ']') {
    ParseClassEscape(ranges, zone(), add_unicode_case_equivalents, &char_1,
                     &is_class_1 CHECK_FAILED);
    // ClassAtom
    if (current() == '-') {
      Advance();
      if (!has_more()) {
        // If we reach the end we break out of the loop and let the
        // following code report an error.
        break;
      } else if (current() == ']') {
        if constexpr (mode == ParseMode::kBuildAST) {
          if (!is_class_1) {
            ranges->Add(CharacterRange::Singleton(char_1), zone());
          }
          ranges->Add(CharacterRange::Singleton('-'), zone());
        }
        break;
      }
      ParseClassEscape(ranges, zone(), add_unicode_case_equivalents, &char_2,
                       &is_class_2 CHECK_FAILED);
      if (is_class_1 || is_class_2) {
        // Either end is an escaped character class. Treat the '-' verbatim.
        if (IsUnicodeMode()) {
          // ES2015 21.2.2.15.1 step 1.
          return ReportError(Error::kInvalidCharacterClass);
        }
        if constexpr (mode == ParseMode::kBuildAST) {
          if (!is_class_1) {
            ranges->Add(CharacterRange::Singleton(char_1), zone());
          }
          ranges->Add(CharacterRange::Singleton('-'), zone());
          if (!is_class_2) {
            ranges->Add(CharacterRange::Singleton(char_2), zone());
          }
        }
        continue;
      }
      // ES2015 21.2.2.15.1 step 6.
      if (char_1 > char_2) {
        return ReportError(Error::kOutOfOrderCharacterClass);
      }
      if constexpr (mode == ParseMode::kBuildAST) {
        ranges->Add(CharacterRange::Range(char_1, char_2), zone());
      }
    } else {
      if constexpr (mode == ParseMode::kBuildAST) {
        if (!is_class_1) ranges->Add(CharacterRange::Singleton(char_1), zone());
      }
    }
  }
  return nullptr;
}

ClassSetResult<mode> ParserImpl<CharT, mode>::ParseClassStringDisjunction(
    ZoneList<CharacterRange>* ranges, CharacterClassStrings* strings) {
  DRPERF_BENCH_REGION("v8-regexp-014");
  DCHECK(unicode_sets());
  DCHECK_EQ(current(), '\\');
  DCHECK_EQ(Next(), 'q');
  Advance(2);
  if (current() != '{') {
    // Identity escape of 'q' is not allowed in unicode mode.
    return ReportError(Error::kInvalidEscape);
  }
  Advance();

  ZoneList<base::uc32>* string =
      zone()->template New<ZoneList<base::uc32>>(4, zone());
  typename TextBuilder<mode>::SmallTreeVector string_storage(zone());
  TextBuilder<mode> string_builder(zone(), &string_storage, flags());

  bool contains_strings = false;
  while (has_more() && current() != '}') {
    if (current() == '|') {
      contains_strings |= AddClassString<mode>(
          string, string_builder.ToRegExp(), ranges, strings, zone());
      string = zone()->template New<ZoneList<base::uc32>>(4, zone());
      string_storage.clear();
      Advance();
    } else {
      base::uc32 c = ParseClassSetCharacter(CHECK_FAILED);
      if (ignore_case()) {
#ifdef V8_INTL_SUPPORT
        c = u_foldCase(c, U_FOLD_CASE_DEFAULT);
#else
        c = AsciiAlphaToLower(c);
#endif
      }
      string->Add(c, zone());
      string_builder.AddUnicodeCharacter(c);
    }
  }

  contains_strings |= AddClassString<mode>(string, string_builder.ToRegExp(),
                                           ranges, strings, zone());
  if constexpr (mode == ParseMode::kBuildAST) {
    CharacterRange::Canonicalize(ranges);
  }

  // We don't need to handle missing closing '}' here.
  // If the character class is correctly closed, ParseClassSetCharacter will
  // report an error.
  Advance();
  return ClassSetResult<mode>(nullptr, contains_strings);
}

ClassSetResult<mode> ParserImpl<CharT, mode>::ParseClassUnion(
    const Builder<mode>* builder, bool is_negated,
    ClassSetResult<mode> first_operand, ClassSetOperandType first_operand_type,
    ZoneList<CharacterRange>* ranges, CharacterClassStrings* strings,
    base::uc32 character) {
  DRPERF_BENCH_REGION("v8-regexp-015");
  DCHECK(unicode_sets());
  ZoneList<Tree*>* operands = nullptr;
  if constexpr (mode == ParseMode::kBuildAST) {
    operands = zone()->template New<ZoneList<Tree*>>(2, zone());
  }
  // Add the lhs to operands if necessary.
  // Either the lhs values were added to |ranges|/|strings| (in which case
  // first_operand.tree is nullptr), or the lhs was evaluated to a tree and
  // passed as |first_operand| (in which case |ranges| and |strings| are empty).
  bool may_contain_strings =
      MayContainStrings(first_operand_type, first_operand);
  if constexpr (mode == ParseMode::kBuildAST) {
    if (first_operand.tree != nullptr) {
      operands->Add(first_operand.tree, zone());
    }
  }
  ClassSetOperandType last_type = first_operand_type;
  while (has_more() && current() != ']') {
    if (current() == '-') {
      // Mix of ClassSetRange and ClassSubtraction is not allowed.
      if (Next() == '-') {
        return ReportError(Error::kInvalidClassSetOperation);
      }
      Advance();
      if (!has_more()) {
        // If we reach the end we break out of the loop and let the
        // following code report an error.
        break;
      }
      // If the lhs and rhs around '-' are both ClassSetCharacters, they
      // represent a character range.
      // In case one of them is not a ClassSetCharacter, it is a syntax error,
      // as '-' can not be used unescaped within a class with /v.
      // See
      // https://tc39.es/ecma262/#prod-ClassSetRange
      if (last_type != ClassSetOperandType::kClassSetCharacter) {
        return ReportError(Error::kInvalidCharacterClass);
      }
      base::uc32 from = character;
      ParseClassSetOperand(builder, &last_type, ranges, strings,
                           &character CHECK_FAILED);
      if (last_type != ClassSetOperandType::kClassSetCharacter) {
        return ReportError(Error::kInvalidCharacterClass);
      }
      if (from > character) {
        return ReportError(Error::kOutOfOrderCharacterClass);
      }
      AddMaybeSimpleCaseFoldedRange(ranges,
                                    CharacterRange::Range(from, character));
      last_type = ClassSetOperandType::kClassSetRange;
    } else {
      DCHECK_NE(current(), '-');
      if (last_type == ClassSetOperandType::kClassSetCharacter) {
        AddMaybeSimpleCaseFoldedRange(ranges,
                                      CharacterRange::Singleton(character));
      }
      ClassSetResult<mode> operand = ParseClassSetOperand(
          builder, &last_type, ranges, strings, &character CHECK_FAILED);
      may_contain_strings |= MayContainStrings(last_type, operand);
      // Add the range we started building as operand and reset the current
      // range.
      if constexpr (mode == ParseMode::kBuildAST) {
        if (operand.tree != nullptr) {
          if (!ranges->is_empty() || !strings->empty()) {
            may_contain_strings |= !strings->empty();
            operands->Add(
                zone()->template New<ClassSetOperand>(ranges, strings), zone());
            ranges = zone()->template New<ZoneList<CharacterRange>>(2, zone());
            strings = zone()->template New<CharacterClassStrings>(zone());
          }
          operands->Add(operand.tree, zone());
        }
      }
    }
  }

  if (!has_more()) {
    return ReportError(Error::kUnterminatedCharacterClass);
  }

  if (last_type == ClassSetOperandType::kClassSetCharacter) {
    AddMaybeSimpleCaseFoldedRange(ranges, CharacterRange::Singleton(character));
  }

  if constexpr (mode == ParseMode::kBuildAST) {
    // Add the range we started building as operand.
    if (!ranges->is_empty() || !strings->empty()) {
      may_contain_strings |= !strings->empty();
      operands->Add(zone()->template New<ClassSetOperand>(ranges, strings),
                    zone());
    }
  }

  DCHECK_EQ(current(), ']');
  Advance();

  if (is_negated && may_contain_strings) {
    return ReportError(Error::kNegatedCharacterClassWithStrings);
  }

  Tree* tree = nullptr;
  if constexpr (mode == ParseMode::kBuildAST) {
    if (operands->is_empty()) {
      // Return empty expression if no operands were added (e.g. [\P{Any}]
      // produces an empty range).
      DCHECK(ranges->is_empty());
      DCHECK(strings->empty());
      tree = ClassSetExpression::Empty(zone(), is_negated);
    } else {
      tree = zone()->template New<ClassSetExpression>(
          ClassSetExpression::OperationType::kUnion, is_negated,
          may_contain_strings, operands);
    }
  }

  return ClassSetResult<mode>(tree, may_contain_strings);
}

ClassSetResult<mode> ParserImpl<CharT, mode>::ParseClassIntersection(
    const Builder<mode>* builder, bool is_negated,
    ClassSetResult<mode> first_operand,
    ClassSetOperandType first_operand_type) {
  DRPERF_BENCH_REGION("v8-regexp-016");
  DCHECK(unicode_sets());
  DCHECK(current() == '&' && Next() == '&');
  bool may_contain_strings =
      MayContainStrings(first_operand_type, first_operand);
  ZoneList<Tree*>* operands = nullptr;
  if constexpr (mode == ParseMode::kBuildAST) {
    operands = zone()->template New<ZoneList<Tree*>>(2, zone());
    DCHECK_NOT_NULL(first_operand.tree);
    operands->Add(first_operand.tree, zone());
  }
  while (has_more() && current() != ']') {
    if (current() != '&' || Next() != '&') {
      return ReportError(Error::kInvalidClassSetOperation);
    }
    Advance(2);
    // [lookahead ≠ &]
    if (current() == '&') {
      return ReportError(Error::kInvalidCharacterInClass);
    }

    ClassSetOperandType operand_type;
    ClassSetResult<mode> operand =
        ParseClassSetOperand(builder, &operand_type CHECK_FAILED);
    may_contain_strings &= MayContainStrings(operand_type, operand);
    if constexpr (mode == ParseMode::kBuildAST) {
      DCHECK_NOT_NULL(operand.tree);
      operands->Add(operand.tree, zone());
    }
  }
  if (!has_more()) {
    return ReportError(Error::kUnterminatedCharacterClass);
  }
  if (is_negated && may_contain_strings) {
    return ReportError(Error::kNegatedCharacterClassWithStrings);
  }
  DCHECK_EQ(current(), ']');
  Advance();
  Tree* tree = nullptr;
  if constexpr (mode == ParseMode::kBuildAST) {
    tree = zone()->template New<ClassSetExpression>(
        ClassSetExpression::OperationType::kIntersection, is_negated,
        may_contain_strings, operands);
  }
  return ClassSetResult<mode>(tree, may_contain_strings);
}

ClassSetResult<mode> ParserImpl<CharT, mode>::ParseClassSubtraction(
    const Builder<mode>* builder, bool is_negated,
    ClassSetResult<mode> first_operand,
    ClassSetOperandType first_operand_type) {
  DRPERF_BENCH_REGION("v8-regexp-017");
  DCHECK(unicode_sets());
  DCHECK(current() == '-' && Next() == '-');
  const bool may_contain_strings =
      MayContainStrings(first_operand_type, first_operand);
  if (is_negated && may_contain_strings) {
    return ReportError(Error::kNegatedCharacterClassWithStrings);
  }
  ZoneList<Tree*>* operands = nullptr;
  if constexpr (mode == ParseMode::kBuildAST) {
    operands = zone()->template New<ZoneList<Tree*>>(2, zone());
    DCHECK_NOT_NULL(first_operand.tree);
    operands->Add(first_operand.tree, zone());
  }
  while (has_more() && current() != ']') {
    if (current() != '-' || Next() != '-') {
      return ReportError(Error::kInvalidClassSetOperation);
    }
    Advance(2);
    ClassSetOperandType dummy;  // unused
    ClassSetResult<mode> operand =
        ParseClassSetOperand(builder, &dummy CHECK_FAILED);
    if constexpr (mode == ParseMode::kBuildAST) {
      DCHECK_NOT_NULL(operand.tree);
      operands->Add(operand.tree, zone());
    }
  }
  if (!has_more()) {
    return ReportError(Error::kUnterminatedCharacterClass);
  }
  DCHECK_EQ(current(), ']');
  Advance();
  Tree* tree = nullptr;
  if constexpr (mode == ParseMode::kBuildAST) {
    tree = zone()->template New<ClassSetExpression>(
        ClassSetExpression::OperationType::kSubtraction, is_negated,
        may_contain_strings, operands);
  }
  return ClassSetResult<mode>(tree, may_contain_strings);
}

ClassSetResult<mode> ParserImpl<CharT, mode>::ParseCharacterClass(
    const Builder<mode>* builder) {
  DRPERF_BENCH_REGION("v8-regexp-018");
  DCHECK_EQ(current(), '[');
  Advance();
  bool is_negated = false;
  if (current() == '^') {
    is_negated = true;
    Advance();
  }
  ZoneList<CharacterRange>* ranges = nullptr;
  if constexpr (mode == ParseMode::kBuildAST) {
    ranges = zone()->template New<ZoneList<CharacterRange>>(2, zone());
  }
  if (current() == ']') {
    Advance();
    Tree* tree = nullptr;
    if constexpr (mode == ParseMode::kBuildAST) {
      if (unicode_sets()) {
        tree = ClassSetExpression::Empty(zone(), is_negated);
      } else {
        ClassRanges::ClassRangesFlags class_ranges_flags;
        if (is_negated) class_ranges_flags = ClassRanges::NEGATED;
        tree = zone()->template New<ClassRanges>(zone(), ranges,
                                                 class_ranges_flags);
      }
    }
    return ClassSetResult<mode>(tree, false);
  }

  if (!unicode_sets()) {
    ParseClassRanges(ranges, add_unicode_case_equivalents() CHECK_FAILED);
    if (!has_more()) {
      return ReportError(Error::kUnterminatedCharacterClass);
    }
    DCHECK_EQ(current(), ']');
    Advance();
    Tree* tree = nullptr;
    if constexpr (mode == ParseMode::kBuildAST) {
      ClassRanges::ClassRangesFlags character_class_flags;
      if (is_negated) character_class_flags = ClassRanges::NEGATED;
      if (!ignore_case()) {
        character_class_flags |= ClassRanges::NO_CASE_FOLDING_NEEDED;
      }
      if (sizeof(CharT) == 1 && !is_negated) {
        // No surrogate pairs.
        character_class_flags |= ClassRanges::IS_CERTAINLY_ONE_CODE_POINT;
      }
      tree = zone()->template New<ClassRanges>(zone(), ranges,
                                               character_class_flags);
    }
    return ClassSetResult<mode>(tree, false);
  } else {
    ClassSetOperandType operand_type;
    CharacterClassStrings* strings = nullptr;
    if constexpr (mode == ParseMode::kBuildAST) {
      strings = zone()->template New<CharacterClassStrings>(zone());
    }
    base::uc32 character;
    ClassSetResult<mode> operand = ParseClassSetOperand(
        builder, &operand_type, ranges, strings, &character CHECK_FAILED);
    switch (current()) {
      case '-':
        if (Next() == '-') {
          if (operand.tree == nullptr) {
            if (operand_type == ClassSetOperandType::kClassSetCharacter) {
              AddMaybeSimpleCaseFoldedRange(
                  ranges, CharacterRange::Singleton(character));
            }
            if constexpr (mode == ParseMode::kBuildAST) {
              operand.tree =
                  zone()->template New<ClassSetOperand>(ranges, strings);
            }
          }
          return ParseClassSubtraction(builder, is_negated, operand,
                                       operand_type);
        }
        // ClassSetRange is handled in ParseClassUnion().
        break;
      case '&':
        if (Next() == '&') {
          if (operand.tree == nullptr) {
            if (operand_type == ClassSetOperandType::kClassSetCharacter) {
              AddMaybeSimpleCaseFoldedRange(
                  ranges, CharacterRange::Singleton(character));
            }
            if constexpr (mode == ParseMode::kBuildAST) {
              operand.tree =
                  zone()->template New<ClassSetOperand>(ranges, strings);
            }
          }
          return ParseClassIntersection(builder, is_negated, operand,
                                        operand_type);
        }
    }
    return ParseClassUnion(builder, is_negated, operand, operand_type, ranges,
                           strings, character);
  }
}

Compiler::CompilationResult Compiler::Assemble(
    Isolate* isolate, RegExpMacroAssembler* macro_assembler, Node* start,
    int capture_count, DirectHandle<RegExpData> re_data) {
  DRPERF_BENCH_REGION("v8-regexp-019");
  macro_assembler_ = macro_assembler;

  auto ReportError = [this]() {
    macro_assembler_->AbortedCodeGeneration();
    return CompilationResult::RegExpTooBig();
  };

  ZoneVector<WorkItem> work_list(zone());
  work_list_ = &work_list;
  NonAssertingLabel fail(this);
  macro_assembler_->set_fail_label(&fail);
  if (!macro_assembler_->prologue_pushes_fail_label()) {
    // The fail label sits at the bottom of the backtrack stack: exhausting all
    // real backtracks pops it and falls through to Fail below. We push it here,
    // before the body is emitted. Assemblers that can elide the backtrack stack
    // defer the push to their prologue instead: backtrack_stack_used() is only
    // final once the whole body is emitted, so only there can they observe that
    // the pattern never backtracks and drop the push (and the stack) entirely.
    macro_assembler_->PushBacktrack(&fail);
  }
  Trace new_trace;
  if (start->Emit(this, &new_trace).IsError()) {
    work_list_ = nullptr;
    return ReportError();
  }
  macro_assembler_->BindJumpTarget(&fail);
  macro_assembler_->Fail();
  while (!work_list.empty()) {
    WorkItem item = work_list.back();
    Node* node = item.node;
    TRACE_WITH_NODE(this, "Popping from worklist ", node);
    work_list.pop_back();
    node->set_on_work_list(false);
    if (!node->label()->is_bound()) {
      if (node->Emit(this, &new_trace).IsError()) {
        work_list_ = nullptr;
        return ReportError();
      }
    }
  }
  if (IsRegExpTooBig()) {
    work_list_ = nullptr;
    return ReportError();
  }

  DirectHandle<HeapObject> code = macro_assembler_->GetCode(re_data, flags_);
  work_list_ = nullptr;

  ComputeQuickCheckFilters(start, re_data);
  return {code, next_register_};
}

EmitResult Trace::Flush(Compiler* compiler, Node* successor,
                        Trace::FlushMode mode) {
  DRPERF_BENCH_REGION("v8-regexp-020");
  RegExpMacroAssembler* assembler = compiler->macro_assembler();
#ifdef V8_ENABLE_REGEXP_DIAGNOSTICS
  if (V8_UNLIKELY(v8_flags.trace_regexp_compiler)) {
    GraphPrinter* printer = compiler->diagnostics()->graph_printer();
    std::ostream& os = compiler->diagnostics()->os();
    os << "* Flushing Trace (";
    switch (mode) {
      case Trace::FlushMode::kFlushFull:
        os << "Full";
        break;
      case Trace::FlushMode::kFlushSuccess:
        os << "Success";
        break;
    }
    os << "): ";
    printer->PrintTrace(this);
    os << std::endl;
  }
#endif

  DCHECK(!is_trivial());

  // Normally we don't need to update the current position register if we are
  // about to stop because we had a successful match, but the global mode
  // requires the current position register to be updated so it can start the
  // next match.  TODO(erikcorry): Perhaps it should use capture register 1
  // instead.
  bool update_current_position =
      cp_offset_ != 0 && (mode != kFlushSuccess || assembler->global());

  if (!has_any_actions() && (backtrack() == nullptr || mode == kFlushSuccess)) {
    // Here we just have some deferred cp advances to fix and we are back to
    // a normal situation.  We may also have to forget some information gained
    // through a quick check that was already performed.
    if (update_current_position) assembler->AdvanceCurrentPosition(cp_offset_);
    // Create a new trivial state and generate the node with that.
    Trace new_state;
    return successor->Emit(compiler, &new_state);
  }

  // Generate deferred actions here along with code to undo them again.
  DynamicBitSet affected_registers;

  // Skip the per-flush bt-stack frame when the successor is an atomic
  // LoopChoice (see AtomicLoopKind): retreating before re-entering
  // the outer scan cannot turn a failed continuation into a match, and the
  // standard restore would make the outer retry O(n^2) on long runs.
  //
  // Two levels of skip:
  //   skip_position_save: drop PushCurrentPosition + PopCurrentPosition.
  //   skip_undo_frame: additionally drop PushBacktrack(&undo) and the undo
  //     body (requires all-IGNORE register undo).  With no frame pushed,
  //     the bt-stack dispatch would pop an outer frame too early, so the
  //     body's failures must GoTo the outer backtrack statically.
  //
  // Besides a single-code-unit body this requires a parked-position grant
  // strong enough for the pending cp advance and the loop kind (see the
  // ParkedGrant levels in regexp-nodes.h).  The gate below mirrors that:
  // kAtEnd/kDisjoint skip at cp_offset_ == 0 under any grant and with a pending
  // prefix only under a uniform-prefix grant; kBoundary skips only under a
  // materialized nonempty uniform prefix.
  LoopChoiceNode* drain_useless_loop = nullptr;
  if (mode == kFlushFull && parked_grant() != ParkedGrant::kNone) {
    DCHECK_NOT_NULL(backtrack());
    // Parking is only sound for a single-code-unit body (see
    // ChooseFixedLengthLoopDrainMode); a wider body could skip a matching start
    // position.
    LoopChoiceNode* loop = successor->AsLoopChoiceNode();
    if (loop != nullptr && loop->FixedLengthBodyIterationLength() == 1) {
      const bool uniform_prefix =
          parked_grant() == ParkedGrant::kParkedUniformPrefix ||
          parked_grant() == ParkedGrant::kParkedNonEmptyUniformPrefix;
      switch (loop->atomic_loop_kind()) {
        case AtomicLoopKind::kNone:
          break;
        case AtomicLoopKind::kAtEnd:
        case AtomicLoopKind::kTotal:
        case AtomicLoopKind::kDisjoint:
          if (cp_offset_ == 0 || (cp_offset_ > 0 && uniform_prefix)) {
            drain_useless_loop = loop;
          }
          break;
        case AtomicLoopKind::kBoundary:
          if (cp_offset_ > 0 && uniform_prefix) {
            drain_useless_loop = loop;
          }
          break;
      }
    }
  }
  bool skip_position_save = drain_useless_loop != nullptr;

  if (!skip_position_save && backtrack() != nullptr && mode != kFlushSuccess) {
    // Here we have a concrete backtrack location.  These are set up by choice
    // nodes and so they indicate that we have a deferred save of the current
    // position which we may need to emit here.
    assembler->PushCurrentPosition();
  }

  int max_register =
      FindAffectedRegisters(&affected_registers, compiler->zone());

  // Decide whether the entire undo frame can be skipped.  Only IGNORE-only
  // undo qualifies: a RESTORE or CLEAR would need a pop or ClearRegisters in
  // the undo body we are dropping.  KeepRecursing gates the inline emit that
  // replaces the AddWork+GoTo fallback.
  bool skip_undo_frame = false;
  if (drain_useless_loop != nullptr &&
      drain_useless_loop->KeepRecursing(compiler)) {
    skip_undo_frame = true;
    for (int reg = 0; reg <= max_register; ++reg) {
      if (!affected_registers.Get(reg)) continue;
      RegisterFlushInfo info;
      ScanDeferredActions(this, reg, &info);
      if (info.undo_action != IGNORE) {
        skip_undo_frame = false;
        break;
      }
    }
  }

  DynamicBitSet registers_to_pop;
  DynamicBitSet registers_to_clear;
  PerformDeferredActions(assembler, max_register, affected_registers,
                         &registers_to_pop, &registers_to_clear,
                         compiler->zone());
  if (update_current_position) assembler->AdvanceCurrentPosition(cp_offset_);

  if (mode == kFlushSuccess) {
    Trace new_state;
    return successor->Emit(compiler, &new_state);
  }

  if (skip_undo_frame) {
    // All-IGNORE undo (pre-scanned above), so PerformDeferredActions pushed
    // no registers and the undo body would be empty: skip PushBacktrack and
    // the undo body; the body's failures GoTo the outer backtrack directly.
    // Call ChoiceNode::Emit to bypass LoopChoiceNode::Emit's
    // non-trivial-trace Flush check (no second frame around this body).
    DCHECK(registers_to_pop.IsEmpty());
    DCHECK(registers_to_clear.IsEmpty());
    Trace new_state;
    new_state.set_backtrack(backtrack());
    // Same target, so our grant transfers.  Materializing a nonempty prefix
    // (cp_offset_ > 0, admitted above only under a uniform-prefix grant)
    // upgrades it to kParkedNonEmptyUniformPrefix; see that enumerator.
    new_state.set_parked_grant(cp_offset_ > 0
                                   ? ParkedGrant::kParkedNonEmptyUniformPrefix
                                   : parked_grant());
    return drain_useless_loop->ChoiceNode::Emit(compiler, &new_state);
  }

  // Create a new trivial state and generate the node with that.
  NonAssertingLabel undo(compiler);
  assembler->PushBacktrack(&undo);
  if (successor->KeepRecursing(compiler)) {
    Trace new_state;
    EmitResult r = successor->Emit(compiler, &new_state);
    if (V8_UNLIKELY(r.IsError())) {
      return r;
    }
  } else {
    compiler->AddWork(successor);
    assembler->GoTo(successor->label());
  }

  // On backtrack we need to restore state.
  assembler->BindJumpTarget(&undo);
  RestoreAffectedRegisters(assembler, max_register, registers_to_pop,
                           registers_to_clear);
  if (backtrack() == nullptr) {
    assembler->Backtrack();
  } else {
    if (!skip_position_save) assembler->PopCurrentPosition();
    assembler->GoTo(backtrack());
  }
  return EmitResult::Success();
}

void GenerateBranches(RegExpMacroAssembler* masm, ZoneList<base::uc32>* ranges,
                      uint32_t start_index, uint32_t end_index,
                      base::uc32 min_char, base::uc32 max_char,
                      Label* fall_through, Label* even_label,
                      Label* odd_label) {
  DRPERF_BENCH_REGION("v8-regexp-021");
  DCHECK_LE(min_char, String::kMaxUtf16CodeUnit);
  DCHECK_LE(max_char, String::kMaxUtf16CodeUnit);

  base::uc32 first = ranges->at(start_index);
  base::uc32 last = ranges->at(end_index) - 1;

  DCHECK_LT(min_char, first);

  // Just need to test if the character is before or on-or-after
  // a particular character.
  if (start_index == end_index) {
    EmitBoundaryTest(masm, first, fall_through, even_label, odd_label);
    return;
  }

  // Another almost trivial case:  There is one interval in the middle that is
  // different from the end intervals.
  if (start_index + 1 == end_index) {
    EmitDoubleBoundaryTest(masm, first, last, fall_through, even_label,
                           odd_label);
    return;
  }

  // It's not worth using table lookup if there are very few intervals in the
  // character class.
  if (end_index - start_index <= 6) {
    // It is faster to test for individual characters, so we look for those
    // first, then try arbitrary ranges in the second round.
    static uint32_t kNoCutIndex = -1;
    uint32_t cut = kNoCutIndex;
    for (uint32_t i = start_index; i < end_index; i++) {
      if (ranges->at(i) == ranges->at(i + 1) - 1) {
        cut = i;
        break;
      }
    }
    if (cut == kNoCutIndex) cut = start_index;
    CutOutRange(masm, ranges, start_index, end_index, cut, even_label,
                odd_label);
    DCHECK_GE(end_index - start_index, 2);
    GenerateBranches(masm, ranges, start_index + 1, end_index - 1, min_char,
                     max_char, fall_through, even_label, odd_label);
    return;
  }

  // If there are a lot of intervals in the regexp, then we will use tables to
  // determine whether the character is inside or outside the character class.
  static const int kBits = RegExpMacroAssembler::kTableSizeBits;

  if ((max_char >> kBits) == (min_char >> kBits)) {
    EmitUseLookupTable(masm, ranges, start_index, end_index, min_char,
                       fall_through, even_label, odd_label);
    return;
  }

  if ((min_char >> kBits) != first >> kBits) {
    masm->CheckCharacterLT(first, odd_label);
    GenerateBranches(masm, ranges, start_index + 1, end_index, first, max_char,
                     fall_through, odd_label, even_label);
    return;
  }

  uint32_t new_start_index = 0;
  uint32_t new_end_index = 0;
  base::uc32 border = 0;

  SplitSearchSpace(ranges, start_index, end_index, &new_start_index,
                   &new_end_index, &border);

  Label handle_rest;
  Label* above = &handle_rest;
  if (border == last + 1) {
    // We didn't find any section that started after the limit, so everything
    // above the border is one of the terminal labels.
    above = (end_index & 1) != (start_index & 1) ? odd_label : even_label;
    DCHECK(new_end_index == end_index - 1);
  }

  DCHECK_LE(start_index, new_end_index);
  DCHECK_LE(new_start_index, end_index);
  DCHECK_LT(start_index, new_start_index);
  DCHECK_LT(new_end_index, end_index);
  DCHECK(new_end_index + 1 == new_start_index ||
         (new_end_index + 2 == new_start_index &&
          border == ranges->at(new_end_index + 1)));
  DCHECK_LT(min_char, border - 1);
  DCHECK_LT(border, max_char);
  DCHECK_LT(ranges->at(new_end_index), border);
  DCHECK(border < ranges->at(new_start_index) ||
         (border == ranges->at(new_start_index) &&
          new_start_index == end_index && new_end_index == end_index - 1 &&
          border == last + 1));
  DCHECK(new_start_index == 0 || border >= ranges->at(new_start_index - 1));

  masm->CheckCharacterGT(border - 1, above);
  Label dummy;
  GenerateBranches(masm, ranges, start_index, new_end_index, min_char,
                   border - 1, &dummy, even_label, odd_label);
  if (handle_rest.is_linked()) {
    masm->Bind(&handle_rest);
    bool flip = (new_start_index & 1) != (start_index & 1);
    GenerateBranches(masm, ranges, new_start_index, end_index, border, max_char,
                     &dummy, flip ? odd_label : even_label,
                     flip ? even_label : odd_label);
  }
}

void EmitClassRanges(Compiler* compiler, RegExpMacroAssembler* macro_assembler,
                     ClassRanges* cr, bool one_byte, Label* on_failure,
                     int cp_offset, bool check_offset, bool preloaded,
                     const QuickCheckDetails::Position* known, Zone* zone) {
  DRPERF_BENCH_REGION("v8-regexp-022");
  ZoneList<CharacterRange>* ranges = cr->ranges(zone);
  CharacterRange::Canonicalize(ranges);

  // Now that all processing (like case-insensitivity) is done, clamp the
  // ranges to the set of ranges that may actually occur in the subject string.
  if (one_byte) CharacterRange::ClampToOneByte(ranges);

  const int ranges_length = ranges->length();
  if (ranges_length == 0) {
    if (!cr->is_negated()) {
      macro_assembler->GoTo(on_failure);
    }
    if (check_offset) {
      macro_assembler->CheckPosition(cp_offset, on_failure);
    }
    return;
  }

  const base::uc32 max_char = MaxCodeUnit(one_byte);
  if (ranges_length == 1 && ranges->at(0).IsEverything(max_char)) {
    if (cr->is_negated()) {
      macro_assembler->GoTo(on_failure);
    } else {
      // This is a common case hit by non-anchored expressions.
      if (check_offset) {
        macro_assembler->CheckPosition(cp_offset, on_failure);
      }
    }
    return;
  }

  if (!preloaded) {
    macro_assembler->LoadCurrentCharacter(cp_offset, on_failure, check_offset);
  }

  if (cr->is_standard(zone) &&
      macro_assembler->CanOptimizeSpecialClassRanges(cr->standard_type())) {
    macro_assembler->CheckSpecialClassRanges(cr->standard_type(), on_failure);
    return;
  }

  // A class whose members differ only in a small set of bits, and which
  // exactly cover the mask equation's solutions within their span, is
  // checked with two fused operations -- (x & M) == c and a range check --
  // instead of a branch tree.  The canonical example is the four suits of
  // one card rank, {0xDCA1, 0xDCB1, 0xDCC1, 0xDCD1}: all solutions of
  // (x & 0xFF8F) == 0xDC81 within [0xDCA1, 0xDCD1] are exactly the class
  // members.
  //
  // Ranges are handled by treating the class as the set of its members: the
  // fold's correctness depends only on which values are present, not on how
  // they were spelled, so [a-c] folds like {a, b, c}.  Enumeration below is
  // O(members), so the member count is capped.
  //
  // Unlike the QuickCheck masked compare, which is only a necessary
  // pre-filter (false positives fall through to the full check), this fold
  // replaces the class check outright, so it must be exact.  Hence we walk
  // the submasks of |diff| below and only fold when every solution in the
  // span is a class member.
  do {
    static constexpr int kMinMembers = 3;
    static constexpr int kMaxMembers = 8;
    const base::uc32 lo = ranges->at(0).from();
    const base::uc32 hi = ranges->at(ranges_length - 1).to();
    if (hi > 0xffff) break;
    // diff = bits that vary across the class members.
    uint32_t diff = 0;
    int member_count = 0;
    for (int i = 0; i < ranges_length; i++) {
      CharacterRange r = ranges->at(i);
      for (base::uc32 ch = r.from(); ch <= r.to(); ch++) {
        if (++member_count > kMaxMembers) break;
        diff |= ch ^ lo;
      }
    }
    if (member_count > kMaxMembers || member_count < kMinMembers) break;
    if (base::bits::CountPopulation(diff) > 4) break;
    // mask pins the non-varying bits to c.
    const uint32_t mask = CharMask(one_byte) & ~diff;
    const uint32_t c = lo & mask;
    // (x & mask) == c is necessary for membership but not sufficient: some
    // other codepoint in [lo, hi] could satisfy it too. Walk every submask
    // of diff (sub = (sub - diff) & diff enumerates them) and fold only if
    // all solutions in the span are class members.
    int solutions = 0;
    for (uint32_t sub = 0;; sub = (sub - diff) & diff) {
      const base::uc32 x = c | sub;
      if (x >= lo && x <= hi) solutions++;
      if (sub == diff) break;
    }
    if (solutions != member_count) break;
    TRACE("* Fold masked class");
    // A passed quick check may have already established (x & M') == c' for
    // a superset mask M' of M; the mask equation then holds and only the
    // range check remains.
    const bool mask_known = known != nullptr && (known->mask & mask) == mask &&
                            (known->value & mask) == c;
    if (!cr->is_negated()) {
      if (!mask_known) {
        macro_assembler->CheckNotCharacterAfterAnd(c, mask, on_failure);
      }
      macro_assembler->CheckCharacterNotInRange(
          static_cast<base::uc16>(lo), static_cast<base::uc16>(hi), on_failure);
    } else if (mask_known) {
      macro_assembler->CheckCharacterInRange(
          static_cast<base::uc16>(lo), static_cast<base::uc16>(hi), on_failure);
    } else {
      Label ok;
      macro_assembler->CheckNotCharacterAfterAnd(c, mask, &ok);
      macro_assembler->CheckCharacterInRange(
          static_cast<base::uc16>(lo), static_cast<base::uc16>(hi), on_failure);
      macro_assembler->Bind(&ok);
    }
    return;
  } while (false);

  static constexpr int kMaxRangesForInlineBranchGeneration = 16;
  if (ranges_length > kMaxRangesForInlineBranchGeneration) {
    // For large range sets, emit a more compact instruction sequence to avoid
    // a potentially problematic increase in code size.
    // Note the flipped logic below (we check InRange if negated, NotInRange if
    // not negated); this is necessary since the method falls through on
    // failure whereas we want to fall through on success.
    if (cr->is_negated()) {
      if (macro_assembler->CheckCharacterInRangeArray(ranges, on_failure)) {
        return;
      }
    } else {
      if (macro_assembler->CheckCharacterNotInRangeArray(ranges, on_failure)) {
        return;
      }
    }
  }

  // Generate a flat list of range boundaries for consumption by
  // GenerateBranches. See the comment on that function for how the list should
  // be structured
  ZoneList<base::uc32>* range_boundaries =
      zone->New<ZoneList<base::uc32>>(ranges_length * 2, zone);

  bool zeroth_entry_is_failure = !cr->is_negated();

  for (int i = 0; i < ranges_length; i++) {
    CharacterRange& range = ranges->at(i);
    if (range.from() == 0) {
      DCHECK_EQ(i, 0);
      zeroth_entry_is_failure = !zeroth_entry_is_failure;
    } else {
      range_boundaries->Add(range.from(), zone);
    }
    // `+ 1` to convert from inclusive to exclusive `to`.
    // [from, to] == [from, to+1[.
    range_boundaries->Add(range.to() + 1, zone);
  }
  int end_index = range_boundaries->length() - 1;
  if (range_boundaries->at(end_index) > max_char) {
    end_index--;
  }

  Label fall_through;
  GenerateBranches(macro_assembler, range_boundaries,
                   0,  // start_index.
                   end_index,
                   0,  // min_char.
                   max_char, &fall_through,
                   zeroth_entry_is_failure ? &fall_through : on_failure,
                   zeroth_entry_is_failure ? on_failure : &fall_through);
  macro_assembler->Bind(&fall_through);
}

bool Node::EmitQuickCheck(Compiler* compiler, Trace* bounds_check_trace,
                          Trace* trace, bool preload_has_checked_bounds,
                          Label* on_possible_success,
                          QuickCheckDetails* details,
                          bool fall_through_on_failure,
                          ChoiceNode* predecessor) {
  DRPERF_BENCH_REGION("v8-regexp-023");
  DCHECK_NOT_NULL(predecessor);
  if (details->characters() == 0) {
    TRACE("* No QuickCheck characters found");
    return false;
  }
  GetQuickCheckDetails(details, compiler, 0,
                       trace->at_start() == Trace::FALSE_VALUE,
                       kRecursionBudget);
  if (details->cannot_match()) {
    TRACE("* QuickCheck cannot match");
    return false;
  }
  if (!details->Rationalize(compiler->one_byte())) {
    TRACE("* QuickCheck didn't find a useful operation");
    return false;
  }
  DCHECK(details->characters() == 1 ||
         compiler->macro_assembler()->CanReadUnaligned());
  uint32_t mask = details->mask();
  uint32_t value = details->value();

  RegExpMacroAssembler* assembler = compiler->macro_assembler();

  TRACE("* Emit QuickCheck");
  if (trace->characters_preloaded() != details->characters()) {
    DCHECK(trace->cp_offset() == bounds_check_trace->cp_offset());
    // The bounds check is performed using the minimum number of characters
    // any choice would eat, so if the bounds check fails, then none of the
    // choices can succeed, so we can just immediately backtrack, rather
    // than go to the next choice. The number of characters preloaded may be
    // less than the number used for the bounds check.
    int eats_at_least = predecessor->EatsAtLeast(
        bounds_check_trace->at_start() == Trace::FALSE_VALUE);
    DCHECK_GE(eats_at_least, details->characters());
    int cp_offset = trace->cp_offset();
    int bounds_check_offset =
        assembler->CalculateBoundsCheckOffset(cp_offset, eats_at_least);
    assembler->LoadCurrentCharacter(cp_offset, bounds_check_trace->backtrack(),
                                    !preload_has_checked_bounds,
                                    details->characters(), bounds_check_offset);
  }

  // Approximate single-character check: prefer an exact membership table (see
  // TryBuildFirstCharacterTable).
  if (details->characters() == 1 &&
      !details->positions(0)->determines_perfectly) {
    const bool not_at_start = trace->at_start() == Trace::FALSE_VALUE;
    Handle<ByteArray> table =
        TryBuildFirstCharacterTable(this, mask, compiler, not_at_start);
    if (!table.is_null()) {
      // The table only proved that the character is in the set. It did not
      // prove the mask equation (x & mask) == value, which we never emitted.
      // Downstream code trusts a published mask/value and would skip a compare
      // on that basis, so clear both (on the position and on the Rationalize()
      // condensate) to signal that nothing is proven here; the body then
      // re-checks in full (see mask_known in EmitClassRanges).
      // The table also proves the low bits every member shares, which we drop
      // here. Keeping them would let the body skip a compare (the "masked-class
      // fold"), but that fold only helps for tightly-grouped character sets,
      // and the table only fires for scattered ones -- so there is nothing to
      // gain today. Revisit if the table ever starts firing for grouped sets
      // too.
      details->positions(0)->mask = 0;
      details->positions(0)->value = 0;
      details->set_mask(0);
      details->set_value(0);
      if (fall_through_on_failure) {
        assembler->CheckBitInTable(table, on_possible_success);
      } else {
        Label matched;
        assembler->CheckBitInTable(table, &matched);
        assembler->GoTo(trace->backtrack());
        assembler->Bind(&matched);
      }
      return true;
    }
  }

  bool need_mask = true;

  if (details->characters() == 1) {
    // If number of characters preloaded is 1 then we used a byte or 16 bit
    // load so the value is already masked down.
    const uint32_t char_mask = CharMask(compiler->one_byte());
    if ((mask & char_mask) == char_mask) need_mask = false;
    mask &= char_mask;
  } else {
    // For 2-character preloads in one-byte mode or 1-character preloads in
    // two-byte mode we also use a 16 bit load with zero extend.
    static const uint32_t kTwoByteMask = 0xFFFF;
    static const uint32_t kFourByteMask = 0xFFFFFFFF;
    if (details->characters() == 2 && compiler->one_byte()) {
      if ((mask & kTwoByteMask) == kTwoByteMask) need_mask = false;
    } else if (details->characters() == 1 && !compiler->one_byte()) {
      if ((mask & kTwoByteMask) == kTwoByteMask) need_mask = false;
    } else {
      if (mask == kFourByteMask) need_mask = false;
    }
  }

  if (fall_through_on_failure) {
    if (need_mask) {
      assembler->CheckCharacterAfterAnd(value, mask, on_possible_success);
    } else {
      assembler->CheckCharacter(value, on_possible_success);
    }
  } else {
    if (need_mask) {
      assembler->CheckNotCharacterAfterAnd(value, mask, trace->backtrack());
    } else {
      assembler->CheckNotCharacter(value, trace->backtrack());
    }
  }
  return true;
}

AtomicLoopBodyAnalysis AnalyzeAtomicLoopBody(
    GuardedAlternative* alt, Node* loop, Zone* zone,
    ZoneList<CharacterRange>* body_set) {
  DRPERF_BENCH_REGION("v8-regexp-024");
  AtomicLoopBodyAnalysis result;
  Node* node = alt->node();
  for (int depth = 0; depth <= Compiler::kMaxRecursion; ++depth) {
    if (node == loop) {
      result.fixed_length_eligible = true;
      return result;
    }
    if (node->FixedLengthLoopLength() ==
        Node::kNodeIsTooComplexForFixedLengthLoops) {
      return result;
    }
    SeqNode* seq = node->AsSeqNode();
    if (seq == nullptr) return result;
    TextNode* text = node->AsTextNode();
    if (text == nullptr || text->read_backward()) {
      result.set_known = false;
    } else {
      ZoneList<TextElement>* elms = text->elements();
      for (int i = 0; i < elms->length(); i++) {
        if (!AppendTextElementMatchSet(elms->at(i), text->zone(), text->flags(),
                                       zone, body_set)) {
          result.set_known = false;
        }
      }
    }
    node = seq->on_success();
  }
  return result;
}

int BoyerMooreLookahead::FindBestInterval(int max_number_of_chars,
                                          int old_biggest_points, int* from,
                                          int* to) {
  DRPERF_BENCH_REGION("v8-regexp-025");
  int biggest_points = old_biggest_points;
  static const int kSize = RegExpMacroAssembler::kTableSize;
  for (int i = 0; i < length_;) {
    while (i < length_ && Count(i) > max_number_of_chars) i++;
    if (i == length_) break;
    int remembered_from = i;

    BoyerMoorePositionInfo::Bitset union_bitset;
    for (; i < length_ && Count(i) <= max_number_of_chars; i++) {
      union_bitset |= bitmaps_->at(i)->raw_bitset();
    }

    int frequency = 0;

    // Iterate only over set bits.
    int j;
    while ((j = BitsetFirstSetBit(union_bitset)) != -1) {
      DCHECK(union_bitset[j]);  // Sanity check.
      // Add 1 to the frequency to give a small per-character boost for
      // the cases where our sampling is not good enough and many
      // characters have a frequency of zero.  This means the frequency
      // can theoretically be up to 2*kSize though we treat it mostly as
      // a fraction of kSize.
      frequency += compiler_->frequency_collator()->Frequency(j) + 1;
      union_bitset.reset(j);
    }

    // We use the probability of skipping times the distance we are skipping to
    // judge the effectiveness of this.  Actually we have a cut-off:  By
    // dividing by 2 we switch off the skipping if the probability of skipping
    // is less than 50%.  This is because the multibyte mask-and-compare
    // skipping in quickcheck is more likely to do well on this case.
    bool in_quickcheck_range =
        ((i - remembered_from < 4) ||
         (compiler_->one_byte() ? remembered_from <= 4 : remembered_from <= 2));
    // Called 'probability' but it is only a rough estimate and can actually
    // be outside the 0-kSize range.
    int probability = (in_quickcheck_range ? kSize / 2 : kSize) - frequency;
    int points = (i - remembered_from) * probability;
    TRACE_COMPILER(compiler_, "  Points for "
                                  << max_number_of_chars << " chars: " << points
                                  << " (start at " << remembered_from
                                  << "; probability: " << probability << ")");
    if (points > biggest_points) {
      *from = remembered_from;
      *to = i - 1;
      biggest_points = points;
    }
  }
  return biggest_points;
}

EmitResult ChoiceNode::EmitChoices(Compiler* compiler,
                                   AlternativeGenerationList* alt_gens,
                                   int first_choice, Trace* trace,
                                   PreloadState* preload,
                                   ParkedGrant body_parked_grant) {
  DRPERF_BENCH_REGION("v8-regexp-026");
  TRACE("* Emit Choices");
  RegExpMacroAssembler* macro_assembler = compiler->macro_assembler();
  SetUpPreLoad(compiler, trace, preload);

  if (first_choice == 0) {
    if (std::optional<EmitResult> dispatched =
            TryEmitMaskedValueDispatch(compiler, alt_gens, trace, preload)) {
      return *dispatched;
    }
  }

  // For now we just call all choices one after the other.  The idea ultimately
  // is to use the Dispatch table to try only the relevant ones.
  int choice_count = alternatives_->length();

  int new_flush_budget = trace->flush_budget() / choice_count;

  bool quick_check_flags =
      v8_flags.regexp_optimization && v8_flags.regexp_quick_check;

  // Landing stub for parked loop-exit backtracks from the body's inline
  // emission; see its use below and the binding after the loop.
  NonAssertingLabel parked_reentry(compiler);

  // An inherited parked-position grant may flow into an alternative only if no
  // sibling can match at a position the park skips (/:|\w*\s/ on "c:" must
  // still match ":" at index 1).  "Floating" = an alternative that can match
  // away from the input start; a start-anchored sibling matches only at
  // position 0, which a park never skips (see AlternativeMatchesOnlyAtStart),
  // so the grant is safe exactly when at most the current alternative floats.
  int floating_alternatives = 0;
  int last_floating = -1;
  if (trace->parked_grant() != ParkedGrant::kNone) {
    for (int i = 0; i < choice_count; i++) {
      if (AlternativeMatchesOnlyAtStart(alternatives_->at(i).node())) continue;
      floating_alternatives++;
      last_floating = i;
    }
  }

  for (int i = first_choice; i < choice_count; i++) {
    bool is_last = i == choice_count - 1;
    bool fall_through_on_failure = !is_last;
    GuardedAlternative alternative = alternatives_->at(i);
    AlternativeGeneration* alt_gen = alt_gens->at(i);
    alt_gen->quick_check_details.set_characters(preload->preload_characters_);
    const ZoneList<Guard*>* guards = alternative.guards();
    int guard_count = (guards == nullptr) ? 0 : guards->length();
    Trace new_trace(*trace);
    const bool siblings_all_anchored =
        floating_alternatives == 0 ||
        (floating_alternatives == 1 && last_floating == i);
    if (!siblings_all_anchored) new_trace.reset_parked_grant();
    new_trace.set_characters_preloaded(
        preload->preload_is_current_ ? preload->preload_characters_ : 0);
    if (preload->preload_has_checked_bounds_) {
      new_trace.set_bound_checked_up_to(preload->preload_characters_);
    }
    new_trace.quick_check_performed()->Clear();
    if (not_at_start_) new_trace.set_at_start(Trace::FALSE_VALUE);
    if (!is_last) {
      // Parked loop-exit backtracks arrive with the position moved,
      // invalidating the preload register and bounds guarantee the next
      // alternative may assume; route them through a checked reload.
      if (body_parked_grant != ParkedGrant::kNone) {
        // The grant is only ever set on the two-alternative search loop, so
        // the granted alternative is the body at index 0.
        DCHECK_EQ(0, i);
        new_trace.set_backtrack(&parked_reentry);
        new_trace.set_parked_grant(body_parked_grant);
      } else {
        new_trace.set_backtrack(&alt_gen->after);
      }
    }
    alt_gen->expects_preload = preload->preload_is_current_;
    bool generate_full_check_inline = false;
    TRACE_WITH_NODE_AND_TRACE(compiler, "  Choice " << i << " ",
                              alternative.node(), &new_trace);
    if (quick_check_flags && try_to_emit_quick_check_for_alternative(i == 0) &&
        alternative.node()->EmitQuickCheck(
            compiler, trace, &new_trace, preload->preload_has_checked_bounds_,
            &alt_gen->possible_success, &alt_gen->quick_check_details,
            fall_through_on_failure, this)) {
      // Quick check was generated for this choice.
      preload->preload_is_current_ = true;
      preload->preload_has_checked_bounds_ = true;
      // If we generated the quick check to fall through on possible success,
      // we now need to generate the full check inline.
      if (!fall_through_on_failure) {
        macro_assembler->Bind(&alt_gen->possible_success);
        new_trace.set_quick_check_performed(&alt_gen->quick_check_details);
        new_trace.set_characters_preloaded(preload->preload_characters_);
        new_trace.set_bound_checked_up_to(preload->preload_characters_);
        generate_full_check_inline = true;
      }
    } else if (alt_gen->quick_check_details.cannot_match()) {
      if (!fall_through_on_failure) {
        macro_assembler->GoTo(trace->backtrack());
      }
      continue;
    } else {
      // No quick check was generated.  Put the full code here.
      // If this is not the first choice then there could be slow checks from
      // previous cases that go here when they fail.  There's no reason to
      // insist that they preload characters since the slow check we are about
      // to generate probably can't use it.
      if (i != first_choice) {
        alt_gen->expects_preload = false;
        new_trace.InvalidateCurrentCharacter();
      }
      generate_full_check_inline = true;
    }
    if (generate_full_check_inline) {
      if (new_trace.has_any_actions()) {
        new_trace.set_flush_budget(new_flush_budget);
      }
      for (int j = 0; j < guard_count; j++) {
        GenerateGuard(macro_assembler, guards->at(j), &new_trace);
      }
      RETURN_IF_ERROR(alternative.node()->Emit(compiler, &new_trace));
      preload->preload_is_current_ = false;
    }
    macro_assembler->Bind(&alt_gen->after);
  }

  if (parked_reentry.is_linked()) {
    // Re-establish the preload register and bounds guarantee with a checked
    // reload before re-entering the advance-and-retry alternative (a parked
    // position can be as far as the subject end).  Running out of input
    // here ends the search: the reload width is bounded by the choice's
    // EatsAtLeast, so every later attempt runs out of input as well.  With
    // preload width zero there is no contract to re-establish.
    macro_assembler->Bind(&parked_reentry);
    if (preload->preload_characters_ > 0) {
      Label out_of_input;
      macro_assembler->LoadCurrentCharacter(trace->cp_offset(), &out_of_input,
                                            true, preload->preload_characters_);
      macro_assembler->GoTo(&alt_gens->at(0)->after);
      macro_assembler->Bind(&out_of_input);
      macro_assembler->GoTo(trace->backtrack());  // Backtracks if null.
    } else {
      macro_assembler->GoTo(&alt_gens->at(0)->after);
    }
  }

  return EmitResult::Success();
}

ZoneList<Instruction> ExperimentalCompiler::Compile(Tree* tree, Flags flags,
                                                    Zone* zone) {
  DRPERF_BENCH_REGION("v8-regexp-027");
  return CompileVisitor::Compile(tree, flags, zone);
}

int ExperimentalRegExpInterpreter::FindMatches(
    Isolate* isolate, RegExp::CallOrigin call_origin,
    Tagged<TrustedByteArray> bytecode, int register_count_per_match,
    Tagged<String> input, int start_index, int32_t* output_registers,
    int output_register_count, Zone* zone) {
  DRPERF_BENCH_REGION("v8-regexp-028");
  DCHECK(input->IsFlat());
  DisallowGarbageCollection no_gc;

  if (input->GetFlatContent(no_gc).IsOneByte()) {
    NfaInterpreter<uint8_t> interpreter(isolate, call_origin, bytecode,
                                        register_count_per_match, input,
                                        start_index, zone);
    return interpreter.FindMatches(output_registers, output_register_count);
  } else {
    DCHECK(input->GetFlatContent(no_gc).IsTwoByte());
    NfaInterpreter<base::uc16> interpreter(isolate, call_origin, bytecode,
                                           register_count_per_match, input,
                                           start_index, zone);
    return interpreter.FindMatches(output_registers, output_register_count);
  }
}
